export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-matplotlib-date-tick-formatter":{"intro":"The ~.dates.ConciseDateFormatter is a useful tool for formatting date ticks when working with Matplotlib. In this lab, you will learn how to use this formatter to improve the strings chosen for the tick labels and to minimize the strings used in those tick labels as much as possible.","steps":[{"title":"Default Formatter","body":["We begin by looking at the default formatter and its verbose output. We plot data over time and see how the default formatter displays the date and time."],"code":[{"lang":"python","text":"import datetime\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.dates as mdates\n\n# create time data\nbase = datetime.datetime(2005, 2, 1)\ndates = [base + datetime.timedelta(hours=(2 * i)) for i in range(732)]\nN = len(dates)\nnp.random.seed(19680801)\ny = np.cumsum(np.random.randn(N))\n\n# plot data\nfig, axs = plt.subplots(3, 1, layout='constrained', figsize=(6, 6))\nlims = [(np.datetime64('2005-02'), np.datetime64('2005-04')),\n        (np.datetime64('2005-02-03'), np.datetime64('2005-02-15')),\n        (np.datetime64('2005-02-03 11:00'), np.datetime64('2005-02-04 13:20'))]\nfor nn, ax in enumerate(axs):\n    ax.plot(dates, y)\n    ax.set_xlim(lims[nn])\n    # rotate labels...\n    for label in ax.get_xticklabels():\n        label.set_rotation(40)\n        label.set_horizontalalignment('right')\naxs[0].set_title('Default Date Formatter')\nplt.show()"}]},{"title":"Concise Date Formatter","body":["Next, we explore the ~.dates.ConciseDateFormatter and its output. We create a new plot with the concise date formatter and see how it differs from the default formatter."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(3, 1, layout='constrained', figsize=(6, 6))\nfor nn, ax in enumerate(axs):\n    locator = mdates.AutoDateLocator(minticks=3, maxticks=7)\n    formatter = mdates.ConciseDateFormatter(locator)\n    ax.xaxis.set_major_locator(locator)\n    ax.xaxis.set_major_formatter(formatter)\n\n    ax.plot(dates, y)\n    ax.set_xlim(lims[nn])\naxs[0].set_title('Concise Date Formatter')\nplt.show()"}]},{"title":"Registering a Converter","body":["If all calls to axes that have dates are to be made using this converter, it is probably most convenient to use the units registry. We register a converter with the units registry and plot data using the concise date formatter."],"code":[{"lang":"python","text":"import datetime\nimport matplotlib.units as munits\n\nconverter = mdates.ConciseDateConverter()\nmunits.registry[np.datetime64] = converter\nmunits.registry[datetime.date] = converter\nmunits.registry[datetime.datetime] = converter\n\nfig, axs = plt.subplots(3, 1, figsize=(6, 6), layout='constrained')\nfor nn, ax in enumerate(axs):\n    ax.plot(dates, y)\n    ax.set_xlim(lims[nn])\naxs[0].set_title('Concise Date Formatter')\nplt.show()"}]},{"title":"Localization of Date Formats","body":["Dates formats can be localized if the default formats are not desirable by manipulating one of three lists of strings. We modify the labels to be \"day month year\", instead of the ISO \"year month day\"."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(3, 1, layout='constrained', figsize=(6, 6))\n\nfor nn, ax in enumerate(axs):\n    locator = mdates.AutoDateLocator()\n    formatter = mdates.ConciseDateFormatter(locator)\n    formatter.formats = ['%y',  # ticks are mostly years\n                         '%b',       # ticks are mostly months\n                         '%d',       # ticks are mostly days\n                         '%H:%M',    # hrs\n                         '%H:%M',    # min\n                         '%S.%f', ]  # secs\n    # these are mostly just the level above...\n    formatter.zero_formats = [''] + formatter.formats[:-1]\n    # ...except for ticks that are mostly hours, then it is nice to have\n    # month-day:\n    formatter.zero_formats[3] = '%d-%b'\n\n    formatter.offset_formats = ['',\n                                '%Y',\n                                '%b %Y',\n                                '%d %b %Y',\n                                '%d %b %Y',\n                                '%d %b %Y %H:%M', ]\n    ax.xaxis.set_major_locator(locator)\n    ax.xaxis.set_major_formatter(formatter)\n\n    ax.plot(dates, y)\n    ax.set_xlim(lims[nn])\naxs[0].set_title('Concise Date Formatter')\nplt.show()"}]},{"title":"Registering a Converter with Localization","body":["Registering a Converter with Localization","We can also register a converter with localization by passing keyword arguments to ~.dates.ConciseDateConverter and registering the datatypes you will use with the units registry."],"code":[{"lang":"python","text":"import datetime\n\nformats = ['%y',          # ticks are mostly years\n           '%b',     # ticks are mostly months\n           '%d',     # ticks are mostly days\n           '%H:%M',  # hrs\n           '%H:%M',  # min\n           '%S.%f', ]  # secs\n# these can be the same, except offset by one level....\nzero_formats = [''] + formats[:-1]\n# ...except for ticks that are mostly hours, then it's nice to have month-day\nzero_formats[3] = '%d-%b'\noffset_formats = ['',\n                  '%Y',\n                  '%b %Y',\n                  '%d %b %Y',\n                  '%d %b %Y',\n                  '%d %b %Y %H:%M', ]\n\nconverter = mdates.ConciseDateConverter(\n    formats=formats, zero_formats=zero_formats, offset_formats=offset_formats)\n\nmunits.registry[np.datetime64] = converter\nmunits.registry[datetime.date] = converter\nmunits.registry[datetime.datetime] = converter\n\nfig, axs = plt.subplots(3, 1, layout='constrained', figsize=(6, 6))\nfor nn, ax in enumerate(axs):\n    ax.plot(dates, y)\n    ax.set_xlim(lims[nn])\naxs[0].set_title('Concise Date Formatter registered non-default')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import datetime\n\nformats = ['%y',          # ticks are mostly years\n           '%b',     # ticks are mostly months\n           '%d',     # ticks are mostly days\n           '%H:%M',  # hrs\n           '%H:%M',  # min\n           '%S.%f', ]  # secs\n# these can be the same, except offset by one level....\nzero_formats = [''] + formats[:-1]\n# ...except for ticks that are mostly hours, then it's nice to have month-day\nzero_formats[3] = '%d-%b'\noffset_formats = ['',\n                  '%Y',\n                  '%b %Y',\n                  '%d %b %Y',\n                  '%d %b %Y',\n                  '%d %b %Y %H:%M', ]\n\nconverter = mdates.ConciseDateConverter(\n    formats=formats, zero_formats=zero_formats, offset_formats=offset_formats)\n\nmunits.registry[np.datetime64] = converter\nmunits.registry[datetime.date] = converter\nmunits.registry[datetime.datetime] = converter\n\nfig, axs = plt.subplots(3, 1, layout='constrained', figsize=(6, 6))\nfor nn, ax in enumerate(axs):\n    ax.plot(dates, y)\n    ax.set_xlim(lims[nn])\naxs[0].set_title('Concise Date Formatter registered non-default')\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-date-demo-convert":{"intro":"Matplotlib is a data visualization library widely used in Python. It is capable of creating various types of graphs and charts such as line charts, bar charts, scatter plots, and more. In this tutorial, we will guide you through the process of creating a date demo convert graph using Matplotlib.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","Before we can start creating the graph, we need to import the required libraries, which are Matplotlib, NumPy, and datetime. Copy and paste the following code:"],"code":[{"lang":"python","text":"import datetime\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.dates import DateFormatter, DayLocator, HourLocator, drange"}]},{"title":"Define the dates and delta","body":["Next, we will define the dates and delta values using the datetime library. The date range will be from March 2, 2000, to March 6, 2000, with a 6-hour interval. Copy and paste the following code:"],"code":[{"lang":"python","text":"date1 = datetime.datetime(2000, 3, 2)\ndate2 = datetime.datetime(2000, 3, 6)\ndelta = datetime.timedelta(hours=6)\ndates = drange(date1, date2, delta)"}]},{"title":"Define the y values","body":["After defining the date range, we will create the y values using NumPy's arange function. The y values will have the same length as the number of dates. Copy and paste the following code:"],"code":[{"lang":"python","text":"y = np.arange(len(dates))"}]},{"title":"Create the graph","body":["Now, we can create the graph using the dates and y values. We will first create a figure and axis object using the subplots function. Then, we will plot the graph using the plot function. Copy and paste the following code:"],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(dates, y**2, 'o')"}]},{"title":"Set the x-axis and format the dates","body":["Set the x-axis and format the dates","To make the graph more readable, we will set the x-axis limits to the first and last dates in the range. We will also set the major and minor locators to DayLocator and HourLocator, respectively. Finally, we will format the dates using the DateFormatter function. Copy and paste the following code:"],"code":[{"lang":"python","text":"ax.set_xlim(dates[0], dates[-1])\nax.xaxis.set_major_locator(DayLocator())\nax.xaxis.set_minor_locator(HourLocator(range(0, 25, 6)))\nax.xaxis.set_major_formatter(DateFormatter('%Y-%m-%d'))\nax.fmt_xdata = DateFormatter('%Y-%m-%d %H:%M:%S')"}]},{"title":"Rotate the x-axis labels","body":["By default, the x-axis labels are in a horizontal orientation. We can rotate the labels to a diagonal orientation to make them more readable. Copy and paste the following code:"],"code":[{"lang":"python","text":"fig.autofmt_xdate()"}]},{"title":"Display the graph","body":["Finally, we can display the graph using the show function. Copy and paste the following code:"],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-date-tick-customization-using-rec":{"intro":"In this lab, you will learn how to use recurrence rules in Matplotlib to place date ticks. The iCalender RFC\\_ specifies recurrence rules (rrules), that define date sequences. You can use rrules in Matplotlib to place date ticks. This example sets custom date ticks on every 5th Easter.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","First, you need to import the necessary libraries, including Matplotlib, NumPy, and datetime."],"code":[{"lang":"python","text":"import datetime\nimport matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.dates import (YEARLY, DateFormatter, RRuleLocator, drange,\n                              rrulewrapper)"}]},{"title":"Set the random seed","body":["You will be generating random data for this example, so you need to set the random seed for reproducibility."],"code":[{"lang":"python","text":"np.random.seed(19680801)"}]},{"title":"Set the recurrence rule","body":["You will be setting custom date ticks on every 5th Easter. To do this, you need to set the recurrence rule using the rrulewrapper function."],"code":[{"lang":"python","text":"rule = rrulewrapper(YEARLY, byeaster=1, interval=5)"}]},{"title":"Set the tick locator and formatter","body":["Set the tick locator and formatter","You will use the RRuleLocator function to set the tick locator based on the recurrence rule you set in the previous step. You will also use the DateFormatter function to set the tick formatter."],"code":[{"lang":"python","text":"loc = RRuleLocator(rule)\nformatter = DateFormatter('%m/%d/%y')"}]},{"title":"Set the dates and generate random data","body":["Set the dates and generate random data","You need to set the start and end dates and the delta, which represents the difference between each date. You also need to generate random data for the example."],"code":[{"lang":"python","text":"date1 = datetime.date(1952, 1, 1)\ndate2 = datetime.date(2004, 4, 12)\ndelta = datetime.timedelta(days=100)\n\ndates = drange(date1, date2, delta)\ns = np.random.rand(len(dates))"}]},{"title":"Plot the data and set the x-axis ticks","body":["Plot the data and set the x-axis ticks","Finally, you can plot the data using the plot function, and set the x-axis ticks using the tick locator and formatter functions you set earlier."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nplt.plot(dates, s, 'o')\nax.xaxis.set_major_locator(loc)\nax.xaxis.set_major_formatter(formatter)\nax.xaxis.set_tick_params(rotation=30, labelsize=10)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nplt.plot(dates, s, 'o')\nax.xaxis.set_major_locator(loc)\nax.xaxis.set_major_formatter(formatter)\nax.xaxis.set_tick_params(rotation=30, labelsize=10)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-date-tick-locators-and-formatters":{"intro":"This lab aims to provide an understanding of how to use the various date tick locators and formatters in Matplotlib. This tutorial demonstrates how to use these functions to customize the X-axis of a plot with time-based data.","steps":[{"title":"Importing Required Libraries","body":["We begin by importing the necessary libraries for this tutorial. We will be using matplotlib and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.dates import (\n    FR, MO, MONTHLY, SA, SU, TH, TU, WE, AutoDateFormatter, AutoDateLocator,\n    ConciseDateFormatter, DateFormatter, DayLocator, HourLocator,\n    MicrosecondLocator, MinuteLocator, MonthLocator, RRuleLocator, SecondLocator,\n    WeekdayLocator, YearLocator, rrulewrapper)\nimport matplotlib.ticker as ticker"}]},{"title":"Defining the Locators and Formatters","body":["Defining the Locators and Formatters","We define the various locators and formatters that we will be using. This example uses the following locators:","• AutoDateLocator(maxticks=8) • YearLocator(month=4) • MonthLocator(bymonth=[4, 8, 12]) • DayLocator(interval=180) • WeekdayLocator(byweekday=SU, interval=4) • HourLocator(byhour=range(0, 24, 6)) • MinuteLocator(interval=15) • SecondLocator(bysecond=(0, 30)) • MicrosecondLocator(interval=1000) • RRuleLocator(rrulewrapper(freq=MONTHLY, byweekday=(MO, TU, WE, TH, FR), bysetpos=-1))","• AutoDateFormatter(ax.xaxis.get_major_locator()) • ConciseDateFormatter(ax.xaxis.get_major_locator()) • DateFormatter(\"%b %Y\")"],"code":[{"lang":"python","text":"locators = [\n    ('AutoDateLocator(maxticks=8)', '2003-02-01', '%Y-%m'),\n    ('YearLocator(month=4)', '2003-02-01', '%Y-%m'),\n    ('MonthLocator(bymonth=[4, 8, 12])', '2003-02-01', '%Y-%m'),\n    ('DayLocator(interval=180)', '2003-02-01', '%Y-%m-%d'),\n    ('WeekdayLocator(byweekday=SU, interval=4)', '2000-07-01', '%a %Y-%m-%d'),\n    ('HourLocator(byhour=range(0, 24, 6))', '2000-02-04', '%H h'),\n    ('MinuteLocator(interval=15)', '2000-02-01 02:00', '%H:%M'),\n    ('SecondLocator(bysecond=(0, 30))', '2000-02-01 00:02', '%H:%M:%S'),\n    ('MicrosecondLocator(interval=1000)', '2000-02-01 00:00:00.005', '%S.%f'),\n    ('RRuleLocator(rrulewrapper(freq=MONTHLY, byweekday=(MO, TU, WE, TH, FR), '\n     'bysetpos=-1))', '2000-07-01', '%Y-%m-%d'),\n]\n\nformatters = [\n    'AutoDateFormatter(ax.xaxis.get_major_locator())',\n    'ConciseDateFormatter(ax.xaxis.get_major_locator())',\n    'DateFormatter(\"%b %Y\")',\n]"}]},{"title":"Plotting the Graphs","body":["Now, we can create our plots. We will create two subplots to demonstrate the locators and formatters separately. For each locator and formatter, we plot a graph that shows how it affects the X-axis. We use the plot_axis function to do this. This function sets up the common parameters for each axis, such as the spines, tick parameters, and limits. It also sets the locator and formatter for the X-axis."],"code":[{"lang":"python","text":"def plot_axis(ax, locator=None, xmax='2002-02-01', fmt=None, formatter=None):\n    ax.spines[['left', 'right', 'top']].set_visible(False)\n    ax.yaxis.set_major_locator(ticker.NullLocator())\n    ax.tick_params(which='major', width=1.00, length=5)\n    ax.tick_params(which='minor', width=0.75, length=2.5)\n    ax.set_xlim(np.datetime64('2000-02-01'), np.datetime64(xmax))\n    if locator:\n        ax.xaxis.set_major_locator(eval(locator))\n        ax.xaxis.set_major_formatter(DateFormatter(fmt))\n    else:\n        ax.xaxis.set_major_formatter(eval(formatter))\n    ax.text(0.0, 0.2, locator or formatter, transform=ax.transAxes,\n            fontsize=14, fontname='Monospace', color='tab:blue')\n\n\nfig, axs = plt.subplots(len(locators), 1, figsize=(8, len(locators) * .8),\n                        layout='constrained')\nfig.suptitle('Date Locators')\nfor ax, (locator, xmax, fmt) in zip(axs, locators):\n    plot_axis(ax, locator, xmax, fmt)\n\nfig, axs = plt.subplots(len(formatters), 1, figsize=(8, len(formatters) * .8),\n                        layout='constrained')\nfig.suptitle('Date Formatters')\nfor ax, fmt in zip(axs, formatters):\n    plot_axis(ax, formatter=fmt)"}]},{"title":"Displaying the Graphs","body":["Finally, we can display the graphs using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-custom-tick-formatter-for-time-series":{"intro":"When plotting daily data such as financial time series, one often wants to leave out days on which there is no data, such as weekends. This allows the data to be plotted at regular intervals without extra spaces for the days with no data. In this lab, we will learn how to use an 'index formatter' to achieve the desired plot.","steps":[{"title":"Import Required Libraries and Data","body":["Import Required Libraries and Data","We first need to import the required libraries, which are matplotlib, numpy, and matplotlib.cbook. We also need to load a numpy record array from yahoo csv data with fields date, open, high, low, close, volume, adj_close from the mpl-data/sample_data directory. The record array stores the date as an np.datetime64 with a day unit ('D') in the date column. We will use this data to plot the financial time series."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.cbook as cbook\n\n# Load data from sample_data directory\nr = cbook.get_sample_data('goog.npz')['price_data'].view(np.recarray)\nr = r[:9]  # get the first 9 days"}]},{"title":"Plotting Data with Default Gaps on Weekends","body":["Plotting Data with Default Gaps on Weekends","We will first plot the data with the default gaps on weekends using the plot function in matplotlib. We will also highlight gaps in the daily data using white dashed lines."],"code":[{"lang":"python","text":"# Plot data with gaps on weekends\nfig, ax1 = plt.subplots(figsize=(6, 3))\nax1.plot(r.date, r.adj_close, 'o-')\n\n# Highlight gaps in daily data\ngaps = np.flatnonzero(np.diff(r.date) > np.timedelta64(1, 'D'))\nfor gap in r[['date', 'adj_close']][np.stack((gaps, gaps + 1)).T]:\n    ax1.plot(gap.date, gap.adj_close, 'w--', lw=2)\nax1.legend(handles=[ml.Line2D([], [], ls='--', label='Gaps in daily data')])\n\nax1.set_title(\"Plotting Data with Default Gaps on Weekends\")\nax1.xaxis.set_major_locator(DayLocator())\nax1.xaxis.set_major_formatter(DateFormatter('%a'))"}]},{"title":"Creating Custom Index Formatter","body":["Creating Custom Index Formatter","To plot the data against an index that goes from 0, 1, ... len(data), we will create a custom index formatter. This formatter will format the tick marks as times instead of integers."],"code":[{"lang":"python","text":"# Create custom index formatter\nfig, ax2 = plt.subplots(figsize=(6, 3))\nax2.plot(r.adj_close, 'o-')\n\n# Format x-axis as times\ndef format_date(x, _):\n    try:\n        # convert datetime64 to datetime, and use datetime's strftime:\n        return r.date[round(x)].item().strftime('%a')\n    except IndexError:\n        pass\n\nax2.set_title(\"Creating Custom Index Formatter\")\nax2.xaxis.set_major_formatter(format_date)  # internally creates FuncFormatter"}]},{"title":"Using a Callable for Formatter","body":["Using a Callable for Formatter","Instead of passing a function into .Axis.set_major_formatter, we can use any other callable, such as an instance of a class that implements __call__. In this step, we will create a class MyFormatter that formats the tick marks as times."],"code":[{"lang":"python","text":"# Use a callable for formatter\nclass MyFormatter(Formatter):\n    def __init__(self, dates, fmt='%a'):\n        self.dates = dates\n        self.fmt = fmt\n\n    def __call__(self, x, pos=0):\n        \"\"\"Return the label for time x at position pos.\"\"\"\n        try:\n            return self.dates[round(x)].item().strftime(self.fmt)\n        except IndexError:\n            pass\n\nax2.xaxis.set_major_formatter(MyFormatter(r.date, '%a'))"}]},{"title":"Displaying the Plot","body":["We will now display the plot using the show function in matplotlib."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-date-precision-and-epochs":{"intro":"This is a step-by-step lab that demonstrates how to handle date precision and epochs in Matplotlib. Matplotlib can work with .datetime objects and numpy.datetime64 objects using a unit converter that recognizes these dates and converts them to floating point numbers. Before Matplotlib 3.3, the default for this conversion returns a float that was days since '0000-12-31T00:00:00'. As of Matplotlib 3.3, the default is days from '1970-01-01T00:00:00'. This allows more resolution for modern dates.","steps":[{"title":"Import necessary packages","body":["The first step is to import the necessary packages, including datetime, matplotlib.pyplot, and numpy."],"code":[{"lang":"python","text":"import datetime\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.dates as mdates"}]},{"title":"Set epoch to the old default","body":["The next step is to set the epoch to the old default, which is days since \"0000-12-31T00:00:00\". This is done using the mdates.set_epoch method."],"code":[{"lang":"python","text":"mdates.set_epoch('0000-12-31T00:00:00')"}]},{"title":"Convert datetime to matplotlib date","body":["Convert datetime to matplotlib date","Now that the epoch has been set, we can convert a datetime object to a Matplotlib date using the mdates.date2num function."],"code":[{"lang":"python","text":"date1 = datetime.datetime(2000, 1, 1, 0, 10, 0, 12, tzinfo=datetime.timezone.utc)\nmdate1 = mdates.date2num(date1)"}]},{"title":"Round-trip the date","body":["We can then round-trip the date using the mdates.num2date function to make sure the conversion is accurate."],"code":[{"lang":"python","text":"date2 = mdates.num2date(mdate1)"}]},{"title":"Set epoch to the new default","body":["To use modern dates at microsecond precision, we need to set the epoch to the new default, which is days since \"1970-01-01T00:00:00\"."],"code":[{"lang":"python","text":"mdates.set_epoch('1970-01-01T00:00:00')"}]},{"title":"Convert datetime to matplotlib date with new epoch","body":["Convert datetime to matplotlib date with new epoch","Now that the epoch has been set to the new default, we can convert a datetime object to a Matplotlib date using the mdates.date2num function."],"code":[{"lang":"python","text":"date1 = datetime.datetime(2020, 1, 1, 0, 10, 0, 12, tzinfo=datetime.timezone.utc)\nmdate1 = mdates.date2num(date1)"}]},{"title":"Round-trip the date with new epoch","body":["Round-trip the date with new epoch","We can then round-trip the date using the mdates.num2date function to make sure the conversion is accurate."],"code":[{"lang":"python","text":"date2 = mdates.num2date(mdate1)"}]},{"title":"Convert numpy.datetime64 to matplotlib date","body":["Convert numpy.datetime64 to matplotlib date","numpy.datetime64 objects have microsecond precision for a much larger timespace than .datetime objects. However, currently, Matplotlib time is only converted back to datetime objects, which have microsecond resolution and years that only span 0000 to 9999."],"code":[{"lang":"python","text":"date1 = np.datetime64('2000-01-01T00:10:00.000012')\nmdate1 = mdates.date2num(date1)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"mdates.set_epoch('1970-01-01T00:00:00')\n\nfig, ax = plt.subplots(layout='constrained')\nax.plot(x, y)\nax.set_title('Epoch: ' + mdates.get_epoch())\nax.xaxis.set_tick_params(rotation=40)\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-anchored-direction-arrow":{"intro":"In this lab, we will learn how to create anchored direction arrows in Matplotlib. Anchored direction arrows are arrows that point in a specific direction and are anchored to a plot. These arrows are useful for indicating specific directions or orientations in a plot. We will learn how to create simple arrows as well as high contrast and rotated arrows.","steps":[{"title":"Import necessary libraries","body":["First, we need to import necessary libraries such as Matplotlib, NumPy, Matplotlib font manager, and AnchoredDirectionArrows from mpl_toolkits.axes_grid1. We will use these libraries to create anchored direction arrows."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nimport matplotlib.font_manager as fm\nfrom mpl_toolkits.axes_grid1.anchored_artists import AnchoredDirectionArrows"}]},{"title":"Create a plot","body":["Next, we will create a simple plot using NumPy. This plot will serve as a background for the anchored direction arrows."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\nfig, ax = plt.subplots()\nax.imshow(np.random.random((10, 10)))"}]},{"title":"Create a simple arrow","body":["Now, we will create a simple anchored direction arrow using the AnchoredDirectionArrows class. This arrow will indicate the X and Y directions in the plot."],"code":[{"lang":"python","text":"# Simple example\nsimple_arrow = AnchoredDirectionArrows(ax.transAxes, 'X', 'Y')\nax.add_artist(simple_arrow)"}]},{"title":"Create a high contrast arrow","body":["Next, we will create a high contrast anchored direction arrow. This arrow will have a white outline and a black fill."],"code":[{"lang":"python","text":"high_contrast_part_1 = AnchoredDirectionArrows(\n                            ax.transAxes,\n                            '111', r'11$\\overline{2}$',\n                            loc='upper right',\n                            arrow_props={'ec': 'w', 'fc': 'none', 'alpha': 1,\n                                         'lw': 2}\n                            )\nax.add_artist(high_contrast_part_1)\n\nhigh_contrast_part_2 = AnchoredDirectionArrows(\n                            ax.transAxes,\n                            '111', r'11$\\overline{2}$',\n                            loc='upper right',\n                            arrow_props={'ec': 'none', 'fc': 'k'},\n                            text_props={'ec': 'w', 'fc': 'k', 'lw': 0.4}\n                            )\nax.add_artist(high_contrast_part_2)"}]},{"title":"Create a rotated arrow","body":["In this step, we will create a rotated anchored direction arrow. This arrow will be rotated by 30 degrees and will have a serif font."],"code":[{"lang":"python","text":"fontprops = fm.FontProperties(family='serif')\n\nrotated_arrow = AnchoredDirectionArrows(\n                    ax.transAxes,\n                    '30', '120',\n                    loc='center',\n                    color='w',\n                    angle=30,\n                    fontproperties=fontprops\n                    )\nax.add_artist(rotated_arrow)"}]},{"title":"Alter the arrow directions","body":["In this step, we will create three anchored direction arrows that point in different directions. These arrows will have different lengths and aspect ratios."],"code":[{"lang":"python","text":"a1 = AnchoredDirectionArrows(\n        ax.transAxes, 'A', 'B', loc='lower center',\n        length=-0.15,\n        sep_x=0.03, sep_y=0.03,\n        color='r'\n    )\nax.add_artist(a1)\n\na2 = AnchoredDirectionArrows(\n        ax.transAxes, 'A', ' B', loc='lower left',\n        aspect_ratio=-1,\n        sep_x=0.01, sep_y=-0.02,\n        color='orange'\n        )\nax.add_artist(a2)\n\n\na3 = AnchoredDirectionArrows(\n        ax.transAxes, ' A', 'B', loc='lower right',\n        length=-0.15,\n        aspect_ratio=-1,\n        sep_y=-0.1, sep_x=0.04,\n        color='cyan'\n        )\nax.add_artist(a3)"}]},{"title":"Display the plot","body":["Finally, we will display the plot with all the anchored direction arrows."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-annotate-figures-with-annotationbbox":{"intro":"In this lab, we will learn how to use AnnotationBbox in Matplotlib to annotate figures using text, shapes, and images. AnnotationBbox is a more fine-grained control method than Axes.annotate. We will go through three different OffsetBoxes: TextArea, DrawingArea, and OffsetImage.","steps":[{"title":"Plotting Points","body":["To start, let's plot two points that we will annotate later."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfig, ax = plt.subplots()\n\n# Define a 1st position to annotate (display it with a marker)\nxy1 = (0.5, 0.7)\nax.plot(xy1[0], xy1[1], \".r\")\n\n# Define a 2nd position to annotate (don't display with a marker this time)\nxy2 = [0.3, 0.55]\n\n# Fix the display limits to see everything\nax.set_xlim(0, 1)\nax.set_ylim(0, 1)\n\nplt.show()"}]},{"title":"Annotating with TextArea","body":["Now let's annotate the first point using a TextArea."],"code":[{"lang":"python","text":"from matplotlib.offsetbox import AnnotationBbox, TextArea\n\n# Annotate the 1st position with a text box ('Test 1')\noffsetbox = TextArea(\"Test 1\")\n\nab = AnnotationBbox(offsetbox, xy1,\n                    xybox=(-20, 40),\n                    xycoords='data',\n                    boxcoords=\"offset points\",\n                    arrowprops=dict(arrowstyle=\"->\"),\n                    bboxprops=dict(boxstyle=\"sawtooth\"))\n\nax.add_artist(ab)\n\nplt.show()"}]},{"title":"Annotating with DrawingArea","body":["Next, let's annotate the second point with a circle patch using DrawingArea."],"code":[{"lang":"python","text":"from matplotlib.offsetbox import DrawingArea\nfrom matplotlib.patches import Circle\n\n# Annotate the 2nd position with a circle patch\nda = DrawingArea(20, 20, 0, 0)\np = Circle((10, 10), 10)\nda.add_artist(p)\n\nab = AnnotationBbox(da, xy2,\n                    xybox=(1., xy2[1]),\n                    xycoords='data',\n                    boxcoords=(\"axes fraction\", \"data\"),\n                    box_alignment=(0.2, 0.5),\n                    arrowprops=dict(arrowstyle=\"->\"),\n                    bboxprops=dict(alpha=0.5))\n\nax.add_artist(ab)\n\nplt.show()"}]},{"title":"Annotating with OffsetImage","body":["Finally, let's annotate the second point with an OffsetImage using an image of Grace Hopper."],"code":[{"lang":"python","text":"from matplotlib.cbook import get_sample_data\nfrom matplotlib.offsetbox import OffsetImage\n\n# Annotate the 2nd position with an image (a generated array of pixels)\narr = np.arange(100).reshape((10, 10))\nim = OffsetImage(arr, zoom=2)\nim.image.axes = ax\n\nab = AnnotationBbox(im, xy2,\n                    xybox=(-50., 50.),\n                    xycoords='data',\n                    boxcoords=\"offset points\",\n                    pad=0.3,\n                    arrowprops=dict(arrowstyle=\"->\"))\n\nax.add_artist(ab)\n\n# Annotate the 2nd position with another image (a Grace Hopper portrait)\nwith get_sample_data(\"grace_hopper.jpg\") as file:\n    arr_img = plt.imread(file)\n\nimagebox = OffsetImage(arr_img, zoom=0.2)\nimagebox.image.axes = ax\n\nab = AnnotationBbox(imagebox, xy2,\n                    xybox=(120., -80.),\n                    xycoords='data',\n                    boxcoords=\"offset points\",\n                    pad=0.5,\n                    arrowprops=dict(\n                        arrowstyle=\"->\",\n                        connectionstyle=\"angle,angleA=0,angleB=90,rad=3\")\n                    )\n\nax.add_artist(ab)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from matplotlib.cbook import get_sample_data\nfrom matplotlib.offsetbox import OffsetImage\n\n# Annotate the 2nd position with an image (a generated array of pixels)\narr = np.arange(100).reshape((10, 10))\nim = OffsetImage(arr, zoom=2)\nim.image.axes = ax\n\nab = AnnotationBbox(im, xy2,\n                    xybox=(-50., 50.),\n                    xycoords='data',\n                    boxcoords=\"offset points\",\n                    pad=0.3,\n                    arrowprops=dict(arrowstyle=\"->\"))\n\nax.add_artist(ab)\n\n# Annotate the 2nd position with another image (a Grace Hopper portrait)\nwith get_sample_data(\"grace_hopper.jpg\") as file:\n    arr_img = plt.imread(file)\n\nimagebox = OffsetImage(arr_img, zoom=0.2)\nimagebox.image.axes = ax\n\nab = AnnotationBbox(imagebox, xy2,\n                    xybox=(120., -80.),\n                    xycoords='data',\n                    boxcoords=\"offset points\",\n                    pad=0.5,\n                    arrowprops=dict(\n                        arrowstyle=\"->\",\n                        connectionstyle=\"angle,angleA=0,angleB=90,rad=3\")\n                    )\n\nax.add_artist(ab)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customizing-matplotlib-axes-and-colorbars":{"intro":"Matplotlib is a Python library that enables the creation of static, animated, and interactive visualizations in Python. It is widely used in scientific computing, data analysis, machine learning, and more. In this lab, you will learn how to plot images using Matplotlib and how to manipulate the location of axes and colorbars.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries that will be used in this lab. We will be using matplotlib.pyplot and cbook from matplotlib to get a sample image."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import cbook"}]},{"title":"Get Demo Image","body":["In this step, we will define a function to get a demo image and its extent. We will be using get_sample_data() function from cbook to get a sample image."],"code":[{"lang":"python","text":"def get_demo_image():\n    z = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")  # 15x15 array\n    return z, (-3, 4, -4, 3)"}]},{"title":"Simple Image and Colorbar","body":["In this step, we will create a simple image and its colorbar. We will be using imshow() function from pyplot to create the image, and colorbar() function to create the colorbar."],"code":[{"lang":"python","text":"def demo_simple_image(ax):\n    Z, extent = get_demo_image()\n\n    im = ax.imshow(Z, extent=extent)\n    cb = plt.colorbar(im)\n    cb.ax.yaxis.set_tick_params(labelright=False)"}]},{"title":"Image and Colorbar with Draw-Time Positioning - A Hard Way","body":["Image and Colorbar with Draw-Time Positioning - A Hard Way","In this step, we will create an image and its colorbar with draw-time positioning in a hard way. We will be using SubplotDivider from mpl_toolkits.axes_grid1 to create a divider for the axes and colorbar."],"code":[{"lang":"python","text":"def demo_locatable_axes_hard(fig):\n    from mpl_toolkits.axes_grid1 import Size, SubplotDivider\n\n    divider = SubplotDivider(fig, 2, 2, 2, aspect=True)\n\n    # axes for image\n    ax = fig.add_subplot(axes_locator=divider.new_locator(nx=0, ny=0))\n    # axes for colorbar\n    ax_cb = fig.add_subplot(axes_locator=divider.new_locator(nx=2, ny=0))\n\n    divider.set_horizontal([\n        Size.AxesX(ax),  # main axes\n        Size.Fixed(0.05),  # padding, 0.1 inch\n        Size.Fixed(0.2),  # colorbar, 0.3 inch\n    ])\n    divider.set_vertical([Size.AxesY(ax)])\n\n    Z, extent = get_demo_image()\n\n    im = ax.imshow(Z, extent=extent)\n    plt.colorbar(im, cax=ax_cb)\n    ax_cb.yaxis.set_tick_params(labelright=False)"}]},{"title":"Image and Colorbar with Draw-Time Positioning - An Easy Way","body":["Image and Colorbar with Draw-Time Positioning - An Easy Way","In this step, we will create an image and its colorbar with draw-time positioning in an easy way. We will be using make_axes_locatable from mpl_toolkits.axes_grid1 to create a divider for the axes and colorbar."],"code":[{"lang":"python","text":"def demo_locatable_axes_easy(ax):\n    from mpl_toolkits.axes_grid1 import make_axes_locatable\n\n    divider = make_axes_locatable(ax)\n\n    ax_cb = divider.append_axes(\"right\", size=\"5%\", pad=0.05)\n    fig = ax.get_figure()\n    fig.add_axes(ax_cb)\n\n    Z, extent = get_demo_image()\n    im = ax.imshow(Z, extent=extent)\n\n    plt.colorbar(im, cax=ax_cb)\n    ax_cb.yaxis.tick_right()\n    ax_cb.yaxis.set_tick_params(labelright=False)"}]},{"title":"Two Images Side by Side with Fixed Padding","body":["Two Images Side by Side with Fixed Padding","In this step, we will create two images side by side with fixed padding. We will be using make_axes_locatable from mpl_toolkits.axes_grid1 to create a divider for the axes and colorbar."],"code":[{"lang":"python","text":"def demo_images_side_by_side(ax):\n    from mpl_toolkits.axes_grid1 import make_axes_locatable\n\n    divider = make_axes_locatable(ax)\n\n    Z, extent = get_demo_image()\n    ax2 = divider.append_axes(\"right\", size=\"100%\", pad=0.05)\n    fig1 = ax.get_figure()\n    fig1.add_axes(ax2)\n\n    ax.imshow(Z, extent=extent)\n    ax2.imshow(Z, extent=extent)\n    ax2.yaxis.set_tick_params(labelleft=False)"}]},{"title":"Plotting","body":["In this step, we will create a figure and add subplots for each image that we want to create."],"code":[{"lang":"python","text":"def demo():\n    fig = plt.figure(figsize=(6, 6))\n\n    # PLOT 1\n    # simple image & colorbar\n    ax = fig.add_subplot(2, 2, 1)\n    demo_simple_image(ax)\n\n    # PLOT 2\n    # image and colorbar with draw-time positioning -- a hard way\n    demo_locatable_axes_hard(fig)\n\n    # PLOT 3\n    # image and colorbar with draw-time positioning -- an easy way\n    ax = fig.add_subplot(2, 2, 3)\n    demo_locatable_axes_easy(ax)\n\n    # PLOT 4\n    # two images side by side with fixed padding.\n    ax = fig.add_subplot(2, 2, 4)\n    demo_images_side_by_side(ax)\n\n    plt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"def demo():\n    fig = plt.figure(figsize=(6, 6))\n\n    # PLOT 1\n    # simple image & colorbar\n    ax = fig.add_subplot(2, 2, 1)\n    demo_simple_image(ax)\n\n    # PLOT 2\n    # image and colorbar with draw-time positioning -- a hard way\n    demo_locatable_axes_hard(fig)\n\n    # PLOT 3\n    # image and colorbar with draw-time positioning -- an easy way\n    ax = fig.add_subplot(2, 2, 3)\n    demo_locatable_axes_easy(ax)\n\n    # PLOT 4\n    # two images side by side with fixed padding.\n    ax = fig.add_subplot(2, 2, 4)\n    demo_images_side_by_side(ax)\n\n    plt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-image-grid-with-matplotlib":{"intro":"This tutorial will demonstrate how to create a grid of images using Matplotlib's ImageGrid. We will create a 2x2 grid of images and explore various ways to add colorbars to the grid.","steps":[{"title":"Import necessary libraries and data","body":["Import necessary libraries and data","We first need to import the necessary libraries and data to create our grid. We will use matplotlib.pyplot for plotting, cbook to get a sample data set, and ImageGrid to create our grid."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import cbook\nfrom mpl_toolkits.axes_grid1 import ImageGrid\n\n# Get sample data\nZ = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")  # 15x15 array\nextent = (-3, 4, -4, 3)"}]},{"title":"Create a grid of 2x2 images with a single colorbar","body":["Create a grid of 2x2 images with a single colorbar","Our first grid will be a 2x2 grid of images with a single colorbar. We will use the ImageGrid function to create the grid and specify the number of rows and columns we want. We will also specify the location of the colorbar and set share_all to True to share the colorbar across all images."],"code":[{"lang":"python","text":"# Create a grid of 2x2 images with a single colorbar\ngrid = ImageGrid(\n    fig,  # Figure object\n    141,  # Location of subplot\n    nrows_ncols=(2, 2),  # Number of rows and columns\n    axes_pad=0.0,  # Padding between axes\n    label_mode=\"L\",  # Label mode\n    share_all=True,  # Share colorbar across all images\n    cbar_location=\"top\",  # Location of colorbar\n    cbar_mode=\"single\"  # Colorbar mode\n)\n\n# Plot images on grid\nfor ax in grid:\n    im = ax.imshow(Z, extent=extent)\n\n# Add colorbar to grid\ngrid.cbar_axes[0].colorbar(im)\nfor cax in grid.cbar_axes:\n    cax.tick_params(labeltop=False)"}]},{"title":"Create a grid of 2x2 images with each image having its own colorbar","body":["Create a grid of 2x2 images with each image having its own colorbar","Our next grid will be a 2x2 grid of images with each image having its own colorbar. We will use the ImageGrid function again, but this time we will set cbar_mode to \"each\" to specify that each image should have its own colorbar."],"code":[{"lang":"python","text":"# Create a grid of 2x2 images with each image having its own colorbar\ngrid = ImageGrid(\n    fig,  # Figure object\n    142,  # Location of subplot\n    nrows_ncols=(2, 2),  # Number of rows and columns\n    axes_pad=0.1,  # Padding between axes\n    label_mode=\"1\",  # Label mode\n    share_all=True,  # Share colorbar across all images\n    cbar_location=\"top\",  # Location of colorbar\n    cbar_mode=\"each\",  # Colorbar mode\n    cbar_size=\"7%\",  # Size of colorbar\n    cbar_pad=\"2%\"  # Padding between colorbar and images\n)\n\n# Plot images on grid and add colorbars\nfor ax, cax in zip(grid, grid.cbar_axes):\n    im = ax.imshow(Z, extent=extent)\n    cax.colorbar(im)\n    cax.tick_params(labeltop=False)"}]},{"title":"Create a grid of 2x2 images with each image having its own colorbar and a different colorbar range","body":["Create a grid of 2x2 images with each image having its own colorbar and a different colorbar range","Our final grid will also be a 2x2 grid of images with each image having its own colorbar, but this time we will use a different colorbar range for each image. We will set the colorbar range using vmin and vmax when plotting each image."],"code":[{"lang":"python","text":"# Create a grid of 2x2 images with each image having its own colorbar and a different colorbar range\ngrid = ImageGrid(\n    fig,  # Figure object\n    143,  # Location of subplot\n    nrows_ncols=(2, 2),  # Number of rows and columns\n    axes_pad=(0.45, 0.15),  # Padding between axes\n    label_mode=\"1\",  # Label mode\n    share_all=True,  # Share colorbar across all images\n    cbar_location=\"right\",  # Location of colorbar\n    cbar_mode=\"each\",  # Colorbar mode\n    cbar_size=\"7%\",  # Size of colorbar\n    cbar_pad=\"2%\"  # Padding between colorbar and images\n)\n\n# Plot images on grid and add colorbars\nlimits = ((0, 1), (-2, 2), (-1.7, 1.4), (-1.5, 1))  # Different colorbar ranges\nfor ax, cax, vlim in zip(grid, grid.cbar_axes, limits):\n    im = ax.imshow(Z, extent=extent, vmin=vlim[0], vmax=vlim[1])\n    cb = cax.colorbar(im)\n    cb.set_ticks((vlim[0], vlim[1]))"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create a grid of 2x2 images with each image having its own colorbar and a different colorbar range\ngrid = ImageGrid(\n    fig,  # Figure object\n    143,  # Location of subplot\n    nrows_ncols=(2, 2),  # Number of rows and columns\n    axes_pad=(0.45, 0.15),  # Padding between axes\n    label_mode=\"1\",  # Label mode\n    share_all=True,  # Share colorbar across all images\n    cbar_location=\"right\",  # Location of colorbar\n    cbar_mode=\"each\",  # Colorbar mode\n    cbar_size=\"7%\",  # Size of colorbar\n    cbar_pad=\"2%\"  # Padding between colorbar and images\n)\n\n# Plot images on grid and add colorbars\nlimits = ((0, 1), (-2, 2), (-1.7, 1.4), (-1.5, 1))  # Different colorbar ranges\nfor ax, cax, vlim in zip(grid, grid.cbar_axes, limits):\n    im = ax.imshow(Z, extent=extent, vmin=vlim[0], vmax=vlim[1])\n    cb = cax.colorbar(im)\n    cb.set_ticks((vlim[0], vlim[1]))"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-imagegrid-demos-for-shared-axes":{"intro":"This tutorial will demonstrate how to use Matplotlib's ImageGrid to create a grid of images with shared x and y axes. The tutorial will cover two demos:","steps":[{"title":"Import necessary libraries","body":["We will use Matplotlib's ImageGrid to create the grid of images. We will also use numpy to generate sample data and cbook to access a sample dataset."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib import cbook\nfrom mpl_toolkits.axes_grid1 import ImageGrid"}]},{"title":"Define a function to add inner titles to the axes","body":["Define a function to add inner titles to the axes","The function add_inner_title will be used to add titles to the images."],"code":[{"lang":"python","text":"def add_inner_title(ax, title, loc, **kwargs):\n    from matplotlib.offsetbox import AnchoredText\n    from matplotlib.patheffects import withStroke\n    prop = dict(path_effects=[withStroke(foreground='w', linewidth=3)],\n                size=plt.rcParams['legend.fontsize'])\n    at = AnchoredText(title, loc=loc, prop=prop,\n                      pad=0., borderpad=0.5,\n                      frameon=False, **kwargs)\n    ax.add_artist(at)\n    return at"}]},{"title":"Prepare the sample data","body":["We will use the get_sample_data function from cbook to obtain sample data. We will then prepare the images to be displayed in the grid."],"code":[{"lang":"python","text":"Z = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")\nextent = (-3, 4, -4, 3)\nZS = [Z[i::3, :] for i in range(3)]\nextent = extent[0], extent[1]/3., extent[2], extent[3]"}]},{"title":"Demo 1 - Colorbar at each axis","body":["Demo 1 - Colorbar at each axis","We will create a grid of 3 images with a colorbar at each axis using the following code:","• We create a grid of 3 images using ImageGrid. • We set the cbar_mode to \"each\" to add a colorbar at each axis. • We set the share_all parameter to True to share the x and y axes across all the images. • We set the cbar_location parameter to \"top\" to position the colorbars at the top. • We set the xticks and yticks for the first image. • We loop through each image and add the image to the axis using imshow. • We add a colorbar to each axis using ax.cax.colorbar. • We set the colorbar ticks for the second and third images. • We add a title to each image using add_inner_title."],"code":[{"lang":"python","text":"grid = ImageGrid(\n    fig, 211, nrows_ncols=(1, 3), axes_pad=0.05, label_mode=\"1\", share_all=True,\n    cbar_location=\"top\", cbar_mode=\"each\", cbar_size=\"7%\", cbar_pad=\"1%\")\ngrid[0].set(xticks=[-2, 0], yticks=[-2, 0, 2])\n\nfor i, (ax, z) in enumerate(zip(grid, ZS)):\n    im = ax.imshow(z, origin=\"lower\", extent=extent)\n    cb = ax.cax.colorbar(im)\n    # Changing the colorbar ticks\n    if i in [1, 2]:\n        cb.set_ticks([-1, 0, 1])\n\nfor ax, im_title in zip(grid, [\"Image 1\", \"Image 2\", \"Image 3\"]):\n    add_inner_title(ax, im_title, loc='lower left')"}]},{"title":"Demo 2 - Shared colorbar","body":["We will create a grid of 3 images with a shared colorbar using the following code:","• We create a grid of 3 images using ImageGrid. • We set the cbar_mode to \"single\" to add a shared colorbar. • We set the share_all parameter to True to share the x and y axes across all the images. • We set the cbar_location parameter to \"right\" to position the colorbar at the right. • We set the xticks and yticks for the first image. • We loop through each image and add the image to the axis using imshow. • We set the clim parameter to ensure that all images use the same color scale. • We add a shared colorbar to the axis using ax.cax.colorbar. • We add a title to each image using add_inner_title."],"code":[{"lang":"python","text":"grid2 = ImageGrid(\n    fig, 212, nrows_ncols=(1, 3), axes_pad=0.05, label_mode=\"1\", share_all=True,\n    cbar_location=\"right\", cbar_mode=\"single\", cbar_size=\"10%\", cbar_pad=0.05)\ngrid2[0].set(xlabel=\"X\", ylabel=\"Y\", xticks=[-2, 0], yticks=[-2, 0, 2])\n\nclim = (np.min(ZS), np.max(ZS))\nfor ax, z in zip(grid2, ZS):\n    im = ax.imshow(z, clim=clim, origin=\"lower\", extent=extent)\n\n# With cbar_mode=\"single\", cax attribute of all axes are identical.\nax.cax.colorbar(im)\n\nfor ax, im_title in zip(grid2, [\"(a)\", \"(b)\", \"(c)\"]):\n    add_inner_title(ax, im_title, loc='upper left')"}]},{"title":"Display the plot","body":["We will use plt.show() to display the plot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-subplot-arrangement-using-hboxdiv":{"intro":"In this lab, we will learn how to use Matplotlib to create subplots using the HBoxDivider and VBoxDivider classes. We will use a simple example to show how these classes can be used to arrange multiple subplots.","steps":[{"title":"Import Required Libraries","body":["We begin by importing the required libraries - matplotlib and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["We create two numpy arrays to be used as the data for our subplots."],"code":[{"lang":"python","text":"arr1 = np.arange(20).reshape((4, 5))\narr2 = np.arange(20).reshape((5, 4))"}]},{"title":"Create Subplots Using HBoxDivider","body":["Create Subplots Using HBoxDivider","We create two subplots side-by-side using the HBoxDivider class. We also adjust the axes' location so that they have equal heights while maintaining their aspect ratios."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2)\nax1.imshow(arr1)\nax2.imshow(arr2)\n\npad = 0.5  # pad in inches\ndivider = HBoxDivider(\n    fig, 111,\n    horizontal=[Size.AxesX(ax1), Size.Fixed(pad), Size.AxesX(ax2)],\n    vertical=[Size.AxesY(ax1), Size.Scaled(1), Size.AxesY(ax2)])\nax1.set_axes_locator(divider.new_locator(0))\nax2.set_axes_locator(divider.new_locator(2))\n\nplt.show()"}]},{"title":"Create Subplots Using VBoxDivider","body":["Create Subplots Using VBoxDivider","We create two subplots one below the other using the VBoxDivider class. We adjust the axes' location so that they have equal widths while maintaining their aspect ratios."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(2, 1)\nax1.imshow(arr1)\nax2.imshow(arr2)\n\ndivider = VBoxDivider(\n    fig, 111,\n    horizontal=[Size.AxesX(ax1), Size.Scaled(1), Size.AxesX(ax2)],\n    vertical=[Size.AxesY(ax1), Size.Fixed(pad), Size.AxesY(ax2)])\n\nax1.set_axes_locator(divider.new_locator(0))\nax2.set_axes_locator(divider.new_locator(2))\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, (ax1, ax2) = plt.subplots(2, 1)\nax1.imshow(arr1)\nax2.imshow(arr2)\n\ndivider = VBoxDivider(\n    fig, 111,\n    horizontal=[Size.AxesX(ax1), Size.Scaled(1), Size.AxesX(ax2)],\n    vertical=[Size.AxesY(ax1), Size.Fixed(pad), Size.AxesY(ax2)])\n\nax1.set_axes_locator(divider.new_locator(0))\nax2.set_axes_locator(divider.new_locator(2))\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-rgb-channels-visualization":{"intro":"Matplotlib is a popular data visualization library in Python. It provides various plotting tools, including 2D and 3D plotting capabilities. In this tutorial, we will use the RGBAxes module of the AxesGrid toolkit in Matplotlib to display RGB channels.","steps":[{"title":"Import necessary libraries","body":["In this step, we will import the necessary libraries: numpy, matplotlib.pyplot, and mpl_toolkits.axes_grid1.axes_rgb."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1.axes_rgb import RGBAxes, make_rgb_axes"}]},{"title":"Define a function to get RGB channels","body":["Define a function to get RGB channels","In this step, we will define a function get_rgb() to get the R, G, and B channels of an image. In this example, we will use the get_sample_data() function of the cbook module to get a sample image."],"code":[{"lang":"python","text":"import matplotlib.cbook as cbook\n\ndef get_rgb():\n    # Get a sample image\n    Z = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")\n    Z[Z < 0] = 0.\n    Z = Z / Z.max()\n\n    # Get R, G, and B channels\n    R = Z[:13, :13]\n    G = Z[2:, 2:]\n    B = Z[:13, 2:]\n\n    return R, G, B"}]},{"title":"Define a function to create a RGB cube","body":["Define a function to create a RGB cube","In this step, we will define a function make_cube() to create a RGB cube from the R, G, and B channels obtained in the previous step. The function will return the R, G, and B cubes, as well as the RGB image."],"code":[{"lang":"python","text":"def make_cube(r, g, b):\n    # Get the shape of R\n    ny, nx = r.shape\n\n    # Create the R, G, and B cubes\n    R = np.zeros((ny, nx, 3))\n    R[:, :, 0] = r\n    G = np.zeros_like(R)\n    G[:, :, 1] = g\n    B = np.zeros_like(R)\n    B[:, :, 2] = b\n\n    # Combine the R, G, and B cubes to create the RGB image\n    RGB = R + G + B\n\n    return R, G, B, RGB"}]},{"title":"Create a RGBAxes plot","body":["In this step, we will create a RGBAxes plot using the RGBAxes class. We will use the imshow_rgb() method of the RGBAxes object to display the RGB image."],"code":[{"lang":"python","text":"def demo_rgb1():\n    # Create a figure and a RGBAxes object\n    fig = plt.figure()\n    ax = RGBAxes(fig, [0.1, 0.1, 0.8, 0.8], pad=0.0)\n\n    # Get the R, G, and B channels\n    r, g, b = get_rgb()\n\n    # Display the RGB image using the imshow_rgb() method\n    ax.imshow_rgb(r, g, b)"}]},{"title":"Create a RGBAxes plot with separate channels","body":["Create a RGBAxes plot with separate channels","In this step, we will create a RGBAxes plot with separate channels using the make_rgb_axes() function. We will use the imshow() method of the Axes objects to display the R, G, and B channels."],"code":[{"lang":"python","text":"def demo_rgb2():\n    # Create a figure and an Axes object\n    fig, ax = plt.subplots()\n\n    # Create the R, G, and B Axes objects using the make_rgb_axes() function\n    ax_r, ax_g, ax_b = make_rgb_axes(ax, pad=0.02)\n\n    # Get the R, G, and B channels and create the RGB cube\n    r, g, b = get_rgb()\n    im_r, im_g, im_b, im_rgb = make_cube(r, g, b)\n\n    # Display the RGB image and the R, G, and B channels\n    ax.imshow(im_rgb)\n    ax_r.imshow(im_r)\n    ax_g.imshow(im_g)\n    ax_b.imshow(im_b)\n\n    # Set the tick parameters and spine colors for all Axes objects\n    for ax in fig.axes:\n        ax.tick_params(direction='in', color='w')\n        ax.spines[:].set_color(\"w\")"}]},{"title":"Display the plots","body":["In this step, we will call the demo_rgb1() and demo_rgb2() functions to create the plots and display them using the plt.show() function."],"code":[{"lang":"python","text":"demo_rgb1()\ndemo_rgb2()\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"demo_rgb1()\ndemo_rgb2()\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-change-axis-direction-in-matplotlib":{"intro":"In this lab, you will learn how to change the axis direction in a Matplotlib plot using the set_axis_direction() method. This method allows you to change the direction of an axis to any of the four cardinal directions: top, bottom, left, or right.","steps":[{"title":"Importing Libraries","body":["First, we need to import the necessary libraries for this lab. We will be using numpy and matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Setting up the Plot","body":["Next, we will define a function setup_axes() that will set up the polar projection in a rectangular box. This function uses GridHelperCurveLinear to create a polar projection with a rectangular box."],"code":[{"lang":"python","text":"from matplotlib.projections import PolarAxes\nfrom matplotlib.transforms import Affine2D\nimport mpl_toolkits.axisartist as axisartist\nimport mpl_toolkits.axisartist.angle_helper as angle_helper\nimport mpl_toolkits.axisartist.grid_finder as grid_finder\nfrom mpl_toolkits.axisartist.grid_helper_curvelinear import \\\n    GridHelperCurveLinear\n\ndef setup_axes(fig, rect):\n    \"\"\"Polar projection, but in a rectangular box.\"\"\"\n    grid_helper = GridHelperCurveLinear(\n        Affine2D().scale(np.pi/180., 1.) + PolarAxes.PolarTransform(),\n        extreme_finder=angle_helper.ExtremeFinderCycle(\n            20, 20,\n            lon_cycle=360, lat_cycle=None,\n            lon_minmax=None, lat_minmax=(0, np.inf),\n        ),\n        grid_locator1=angle_helper.LocatorDMS(12),\n        grid_locator2=grid_finder.MaxNLocator(5),\n        tick_formatter1=angle_helper.FormatterDMS(),\n    )\n    ax = fig.add_subplot(\n        rect, axes_class=axisartist.Axes, grid_helper=grid_helper,\n        aspect=1, xlim=(-5, 12), ylim=(-5, 10))\n    ax.axis[:].toggle(ticklabels=False)\n    ax.grid(color=\".9\")\n    return ax"}]},{"title":"Adding Floating Axis","body":["We will define two functions that will add floating axes to our plot. The first function add_floating_axis1() adds a floating axis to the plot with a label of theta = 30. The second function add_floating_axis2() adds a floating axis to the plot with a label of r = 6."],"code":[{"lang":"python","text":"def add_floating_axis1(ax):\n    ax.axis[\"lat\"] = axis = ax.new_floating_axis(0, 30)\n    axis.label.set_text(r\"$\\theta = 30^{\\circ}$\")\n    axis.label.set_visible(True)\n    return axis\n\ndef add_floating_axis2(ax):\n    ax.axis[\"lon\"] = axis = ax.new_floating_axis(1, 6)\n    axis.label.set_text(r\"$r = 6$\")\n    axis.label.set_visible(True)\n    return axis"}]},{"title":"Changing the Axis Direction","body":["Now, we will create a loop to set up four different plots with the floating axis in each of the four cardinal directions. In the loop, we will use add_floating_axis1() and add_floating_axis2() to add the floating axes, and set_axis_direction() to set the axis direction."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(8, 4), layout=\"constrained\")\n\nfor i, d in enumerate([\"bottom\", \"left\", \"top\", \"right\"]):\n    ax = setup_axes(fig, rect=241+i)\n    axis = add_floating_axis1(ax)\n    axis.set_axis_direction(d)\n    ax.set(title=d)\n\nfor i, d in enumerate([\"bottom\", \"left\", \"top\", \"right\"]):\n    ax = setup_axes(fig, rect=245+i)\n    axis = add_floating_axis2(ax)\n    axis.set_axis_direction(d)\n    ax.set(title=d)\n\nplt.show()"}]},{"title":"Viewing the Plot","body":["Finally, we will view the plot. We can see the same plot with the floating axis in each of the four cardinal directions."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-axis-line-styles":{"intro":"In this lab, we will learn how to configure axis style in Matplotlib. We will be using the mpl_toolkits.axisartist axes classes to add arrows at the ends of each axis and to add X and Y-axis from the origin. We will also hide the borders of the plot.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits.axisartist.axislines import AxesZero"}]},{"title":"Create Figure and Subplot","body":["Next, we will create a figure and a subplot."],"code":[{"lang":"python","text":"fig = plt.figure()\nax = fig.add_subplot(axes_class=AxesZero)"}]},{"title":"Configure Axis Style","body":["We will now configure the axis style by adding arrows at the ends of each axis and adding X and Y-axis from the origin."],"code":[{"lang":"python","text":"for direction in [\"xzero\", \"yzero\"]:\n    # adds arrows at the ends of each axis\n    ax.axis[direction].set_axisline_style(\"-|>\")\n    # adds X and Y-axis from the origin\n    ax.axis[direction].set_visible(True)\n\n# hides borders\nfor direction in [\"left\", \"right\", \"bottom\", \"top\"]:\n    ax.axis[direction].set_visible(False)"}]},{"title":"Plot the Graph","body":["We will now plot the graph using np.linspace and np.sin."],"code":[{"lang":"python","text":"x = np.linspace(-0.5, 1., 100)\nax.plot(x, np.sin(x*np.pi))"}]},{"title":"Display the Graph","body":["Finally, we will display the graph using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-bboximage-in-matplotlib":{"intro":"In this lab, you will learn how to create a BboxImage in Matplotlib. A BboxImage can be used to position an image according to a bounding box. We will show how to create a BboxImage with Text and how to create a BboxImage for each colormap.","steps":[{"title":"Import necessary libraries","body":["We start by importing the necessary libraries for this tutorial. We will need matplotlib.pyplot, numpy, BboxImage, Bbox and TransformedBbox."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.image import BboxImage\nfrom matplotlib.transforms import Bbox, TransformedBbox"}]},{"title":"Create a BboxImage with Text","body":["We start by creating a BboxImage with Text. We create a text object with the text() method and add it to the ax1 object. We then create a BboxImage object using the add_artist() method. We pass the get_window_extent method of the text object to the BboxImage constructor to get the bounding box for the text. We also pass a 1D array of shape (1, 256) to the data parameter of the BboxImage constructor to create an image."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(ncols=2)\n\ntxt = ax1.text(0.5, 0.5, \"test\", size=30, ha=\"center\", color=\"w\")\nax1.add_artist(\n    BboxImage(txt.get_window_extent, data=np.arange(256).reshape((1, -1))))"}]},{"title":"Create a BboxImage for each colormap","body":["Create a BboxImage for each colormap","Next, we create a BboxImage for each colormap. We start by creating a list of all colormaps using the plt.colormaps method. We then create a for loop that iterates through the list of colormaps. For each colormap, we calculate the ix and iy position using the divmod() method. We then create a Bbox object using the Bbox.from_bounds() method. We pass the ix, iy, dx, and dy values to the Bbox.from_bounds() method to create the bounding box. We then create a TransformedBbox object using the Bbox object and the ax2.transAxes object. Finally, we create a BboxImage object using the add_artist() method. We pass the TransformedBbox…"],"code":[{"lang":"python","text":"cmap_names = sorted(m for m in plt.colormaps if not m.endswith(\"_r\"))\n\nncol = 2\nnrow = len(cmap_names) // ncol + 1\n\nxpad_fraction = 0.3\ndx = 1 / (ncol + xpad_fraction * (ncol - 1))\n\nypad_fraction = 0.3\ndy = 1 / (nrow + ypad_fraction * (nrow - 1))\n\nfor i, cmap_name in enumerate(cmap_names):\n    ix, iy = divmod(i, nrow)\n    bbox0 = Bbox.from_bounds(ix*dx*(1+xpad_fraction),\n                             1 - iy*dy*(1+ypad_fraction) - dy,\n                             dx, dy)\n    bbox = TransformedBbox(bbox0, ax2.transAxes)\n    ax2.add_artist(\n        BboxImage(bbox, cmap=cmap_name, data=np.arange(256).reshape((1, -1))))"}]},{"title":"Show the plot","body":["Finally, we show the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-adding-a-colorbar-to-inset-axes":{"intro":"In this lab, you will learn how to add a colorbar to inset axes using Matplotlib in Python. A colorbar is a visual representation of the mapping of a range of colors to a range of numerical values. An inset axis is a smaller axis that is placed within the larger axis of a plot.","steps":[{"title":"Import Libraries and Data","body":["First, import the necessary libraries and data that will be used in the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import cbook\nfrom mpl_toolkits.axes_grid1.inset_locator import inset_axes, zoomed_inset_axes\n\nfig, ax = plt.subplots(figsize=[5, 4])\n\nZ = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")\nextent = (-3, 4, -4, 3)"}]},{"title":"Set the Main Plot","body":["Set the main plot by adjusting the aspect ratio and the limits of the x and y axes."],"code":[{"lang":"python","text":"ax.set(aspect=1, xlim=(-15, 15), ylim=(-20, 5))"}]},{"title":"Create an Inset Axis","body":["Create an inset axis using the zoomed_inset_axes function. Set the zoom level and the location of the inset axis within the main plot."],"code":[{"lang":"python","text":"axins = zoomed_inset_axes(ax, zoom=2, loc='upper left')\naxins.set(xticks=[], yticks=[])"}]},{"title":"Add an Image to the Inset Axis","body":["Add an Image to the Inset Axis","Add an image to the inset axis using the imshow function. Set the extent and the origin of the image."],"code":[{"lang":"python","text":"im = axins.imshow(Z, extent=extent, origin=\"lower\")"}]},{"title":"Add a Colorbar","body":["Add a colorbar to the inset axis using the inset_axes function. Set the width, height, location, and bounding box of the colorbar."],"code":[{"lang":"python","text":"cax = inset_axes(axins,\n                 width=\"5%\",  # width = 10% of parent_bbox width\n                 height=\"100%\",  # height : 50%\n                 loc='lower left',\n                 bbox_to_anchor=(1.05, 0., 1, 1),\n                 bbox_transform=axins.transAxes,\n                 borderpad=0,\n                 )\nfig.colorbar(im, cax=cax)"}]},{"title":"Display the Plot","body":["Display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-add-colorbar-to-matplotlib-plot":{"intro":"Matplotlib is a Python library used for data visualization. In this lab, we will learn how to add a colorbar to a plot in Matplotlib. Colorbars are useful for indicating the range of values that a colormap represents.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries. We will be using Matplotlib's pyplot module, which provides an interface for creating plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a plot","body":["Next, we will create a plot using Matplotlib's imshow function. This function displays an image on the plot. We will also create a figure with two subplots."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2)\nfig.subplots_adjust(wspace=0.5)\n\nim1 = ax1.imshow([[1, 2], [3, 4]])\n\nim2 = ax2.imshow([[1, 2], [3, 4]])"}]},{"title":"Add a colorbar to the plot","body":["Now, we will add a colorbar to each subplot using Matplotlib's make_axes_locatable function. This function takes an existing axes, adds it to a new AxesDivider and returns the AxesDivider. The append_axes method of the AxesDivider can then be used to create a new axes on a given side (\"top\", \"right\", \"bottom\", or \"left\") of the original axes."],"code":[{"lang":"python","text":"ax1_divider = make_axes_locatable(ax1)\ncax1 = ax1_divider.append_axes(\"right\", size=\"7%\", pad=\"2%\")\ncb1 = fig.colorbar(im1, cax=cax1)\n\nax2_divider = make_axes_locatable(ax2)\ncax2 = ax2_divider.append_axes(\"top\", size=\"7%\", pad=\"2%\")\ncb2 = fig.colorbar(im2, cax=cax2, orientation=\"horizontal\")\ncax2.xaxis.set_ticks_position(\"top\")"}]},{"title":"Display the plot","body":["Finally, we will display the plot using Matplotlib's show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-colorbar-inset-axes":{"intro":"This tutorial will show you how to control the position, height, and width of colorbars using mpl_toolkits.axes_grid1.inset_locator.inset_axes. This is useful when you want to add a colorbar to your plot but want to customize its size and position.","steps":[{"title":"Import Required Libraries","body":["First, we need to import the required libraries: matplotlib and inset_axes from mpl_toolkits.axes_grid1."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1.inset_locator import inset_axes"}]},{"title":"Create Plot and Image","body":["Next, we will create a plot and an image to show how to add a colorbar using inset axes."],"code":[{"lang":"python","text":"fig, (ax1, ax2) = plt.subplots(1, 2, figsize=[6, 3])\n\nim1 = ax1.imshow([[1, 2], [2, 3]])\nim2 = ax2.imshow([[1, 2], [2, 3]])"}]},{"title":"Add Colorbar using Inset Axes","body":["Now, we will add a colorbar to each of the images using inset_axes. The first colorbar will be added to ax1 and the second to ax2."],"code":[{"lang":"python","text":"# add colorbar to ax1\naxins1 = inset_axes(\n    ax1,\n    width=\"50%\",  # width: 50% of parent_bbox width\n    height=\"5%\",  # height: 5%\n    loc=\"upper right\",\n)\naxins1.xaxis.set_ticks_position(\"bottom\")\nfig.colorbar(im1, cax=axins1, orientation=\"horizontal\", ticks=[1, 2, 3])\n\n# add colorbar to ax2\naxins2 = inset_axes(\n    ax2,\n    width=\"5%\",  # width: 5% of parent_bbox width\n    height=\"50%\",  # height: 50%\n    loc=\"lower left\",\n    bbox_to_anchor=(1.05, 0., 1, 1),\n    bbox_transform=ax2.transAxes,\n    borderpad=0,\n)\nfig.colorbar(im2, cax=axins2, ticks=[1, 2, 3])"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-resizing-axes-with-constrained-layout":{"intro":"In data visualization, it is crucial to have clear and readable plots. However, creating multiple subplots can make it difficult to avoid overlaps between axes objects and labels. In such cases, we can use a feature called _constrained layout_ in Matplotlib, which automatically resizes subplots to prevent overlaps between axes objects and labels.","steps":[{"title":"Importing Required Libraries","body":["We start by importing the necessary libraries for creating subplots and plotting data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.gridspec as gridspec"}]},{"title":"Defining Example Plot","body":["We define a function that creates a simple line plot with x and y labels and a title."],"code":[{"lang":"python","text":"def example_plot(ax):\n    ax.plot([1, 2])\n    ax.set_xlabel('x-label', fontsize=12)\n    ax.set_ylabel('y-label', fontsize=12)\n    ax.set_title('Title', fontsize=14)"}]},{"title":"Creating Subplots Without Constrained Layout","body":["Creating Subplots Without Constrained Layout","We create a figure with 2x2 subplots without using _constrained layout_. This results in overlapping labels on the axes."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=2, ncols=2, layout=None)\n\nfor ax in axs.flat:\n    example_plot(ax)"}]},{"title":"Creating Subplots with Constrained Layout","body":["Creating Subplots With Constrained Layout","We create the same 2x2 subplots, but this time we use _constrained layout_. This automatically adjusts the subplots to prevent overlaps between axes objects and labels."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=2, ncols=2, layout='constrained')\n\nfor ax in axs.flat:\n    example_plot(ax)"}]},{"title":"Creating Nested Gridspecs with Constrained Layout","body":["Creating Nested Gridspecs with Constrained Layout","We create a more complicated example by using nested gridspecs with _constrained layout_. This allows us to have more control over the layout of the subplots."],"code":[{"lang":"python","text":"fig = plt.figure(layout='constrained')\n\ngs0 = gridspec.GridSpec(1, 2, figure=fig)\n\ngs1 = gridspec.GridSpecFromSubplotSpec(3, 1, subplot_spec=gs0[0])\nfor n in range(3):\n    ax = fig.add_subplot(gs1[n])\n    example_plot(ax)\n\n\ngs2 = gridspec.GridSpecFromSubplotSpec(2, 1, subplot_spec=gs0[1])\nfor n in range(2):\n    ax = fig.add_subplot(gs2[n])\n    example_plot(ax)\n\nplt.show()"}]},{"title":"Summary","body":["_Constrained layout_ is a useful feature in Matplotlib that automatically resizes subplots to prevent overlaps between axes objects and labels. It is particularly useful when creating multiple subplots in a figure. By following the steps outlined in this tutorial, you can create clear and readable plots without having to worry about overlapping labels."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-curvilinear-grid":{"intro":"In this lab, we will learn how to use GridHelperCurveLinear to create custom grid and tick lines in Matplotlib. We will also learn how to create a polar projection in a rectangular box.","steps":[{"title":"Grid for Custom Transform","body":["First, we will create a custom grid and tick lines using GridHelperCurveLinear. The custom transform will be applied to the grid and tick lines. The following code demonstrates this process:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.projections import PolarAxes\nfrom matplotlib.transforms import Affine2D\nfrom mpl_toolkits.axisartist import Axes, HostAxes, angle_helper\nfrom mpl_toolkits.axisartist.grid_helper_curvelinear import GridHelperCurveLinear\n\ndef curvelinear_test1(fig):\n    # Define custom transform\n    def tr(x, y):\n        return x, y - x\n    def inv_tr(x, y):\n        return x, y + x\n\n    # Create GridHelperCurveLinear object\n    grid_helper = GridHelperCurveLinear((tr, inv_tr))\n\n    # Create a subplot with the custom grid and tick lines\n    ax1 = fig.add_subplot(1, 2, 1, axes_class=Axes, grid_helper=grid_helper)\n\n    # Plot some points on the subplot\n    xx, yy = tr(np.array([3, 6]), np.array([5, 10]))\n    ax1.plot(xx, yy)\n\n    # Set the aspect ratio and limits of the subplot\n    ax1.set_aspect(1)\n    ax1.set_xlim(0, 10)\n    ax1.set_ylim(0, 10)\n\n    # Add floating axes and grid lines\n    ax1.axis[\"t\"] = ax1.new_floating_axis(0, 3)\n    ax1.axis[\"t2\"] = ax1.new_floating_axis(1, 7)\n    ax1.grid(True, zorder=0)\n\nfig = plt.figure(figsize=(7, 4))\ncurvelinear_test1(fig)\nplt.show()"}]},{"title":"Polar Projection in a Rectangular Box","body":["Polar Projection in a Rectangular Box","Next, we will create a polar projection in a rectangular box using GridHelperCurveLinear. We will use an Affine2D transform to scale the degree coordinates to radians, and PolarAxes.PolarTransform to create the polar projection. We will also use angle_helper.ExtremeFinderCycle to find the extremes of the polar projection, and angle_helper.LocatorDMS and angle_helper.FormatterDMS to format the tick labels. The following code demonstrates this process:"],"code":[{"lang":"python","text":"def curvelinear_test2(fig):\n    # Define the custom transform\n    tr = Affine2D().scale(np.pi/180, 1) + PolarAxes.PolarTransform()\n\n    # Define the extreme finder, grid locator, and tick formatter\n    extreme_finder = angle_helper.ExtremeFinderCycle(\n        nx=20, ny=20,\n        lon_cycle=360, lat_cycle=None,\n        lon_minmax=None, lat_minmax=(0, np.inf),\n    )\n    grid_locator1 = angle_helper.LocatorDMS(12)\n    tick_formatter1 = angle_helper.FormatterDMS()\n\n    # Create GridHelperCurveLinear object\n    grid_helper = GridHelperCurveLinear(\n        tr, extreme_finder=extreme_finder,\n        grid_locator1=grid_locator1, tick_formatter1=tick_formatter1)\n    ax1 = fig.add_subplot(\n        1, 2, 2, axes_class=HostAxes, grid_helper=grid_helper)\n\n    # Make ticklabels of right and top axis visible\n    ax1.axis[\"right\"].major_ticklabels.set_visible(True)\n    ax1.axis[\"top\"].major_ticklabels.set_visible(True)\n\n    # Let right axis show ticklabels for 1st coordinate (angle)\n    ax1.axis[\"right\"].get_helper().nth_coord_ticks = 0\n\n    # Let bottom axis show ticklabels for 2nd coordinate (radius)\n    ax1.axis[\"bottom\"].get_helper().nth_coord_ticks = 1\n\n    # Set the aspect ratio and limits of the subplot\n    ax1.set_aspect(1)\n    ax1.set_xlim(-5, 12)\n    ax1.set_ylim(-5, 10)\n\n    # Add grid lines to the subplot\n    ax1.grid(True, zorder=0)\n\n    # Create a parasite axes with the given transform\n    ax2 = ax1.get_aux_axes(tr)\n\n    # Anything you draw in ax2 will match the ticks and grids of ax1.\n    ax2.plot(np.linspace(0, 30, 51), np.linspace(10, 10, 51), linewidth=2)\n\n    ax2.pcolor(np.linspace(0, 90, 4), np.linspace(0, 10, 4),\n               np.arange(9).reshape((3, 3)))\n    ax2.contour(np.linspace(0, 90, 4), np.linspace(0, 10, 4),\n                np.arange(16).reshape((4, 4)), colors=\"k\")"}]},{"title":"Final Code","body":["The final code combines the code from Step 1 and Step 2:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.projections import PolarAxes\nfrom matplotlib.transforms import Affine2D\nfrom mpl_toolkits.axisartist import Axes, HostAxes, angle_helper\nfrom mpl_toolkits.axisartist.grid_helper_curvelinear import GridHelperCurveLinear\n\ndef curvelinear_test1(fig):\n    # Define custom transform\n    def tr(x, y):\n        return x, y - x\n    def inv_tr(x, y):\n        return x, y + x\n\n    # Create GridHelperCurveLinear object\n    grid_helper = GridHelperCurveLinear((tr, inv_tr))\n\n    # Create a subplot with the custom grid and tick lines\n    ax1 = fig.add_subplot(1, 2, 1, axes_class=Axes, grid_helper=grid_helper)\n\n    # Plot some points on the subplot\n    xx, yy = tr(np.array([3, 6]), np.array([5, 10]))\n    ax1.plot(xx, yy)\n\n    # Set the aspect ratio and limits of the subplot\n    ax1.set_aspect(1)\n    ax1.set_xlim(0, 10)\n    ax1.set_ylim(0, 10)\n\n    # Add floating axes and grid lines\n    ax1.axis[\"t\"] = ax1.new_floating_axis(0, 3)\n    ax1.axis[\"t2\"] = ax1.new_floating_axis(1, 7)\n    ax1.grid(True, zorder=0)\n\ndef curvelinear_test2(fig):\n    # Define the custom transform\n    tr = Affine2D().scale(np.pi/180, 1) + PolarAxes.PolarTransform()\n\n    # Define the extreme finder, grid locator, and tick formatter\n    extreme_finder = angle_helper.ExtremeFinderCycle(\n        nx=20, ny=20,\n        lon_cycle=360, lat_cycle=None,\n        lon_minmax=None, lat_minmax=(0, np.inf),\n    )\n    grid_locator1 = angle_helper.LocatorDMS(12)\n    tick_formatter1 = angle_helper.FormatterDMS()\n\n    # Create GridHelperCurveLinear object"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.projections import PolarAxes\nfrom matplotlib.transforms import Affine2D\nfrom mpl_toolkits.axisartist import Axes, HostAxes, angle_helper\nfrom mpl_toolkits.axisartist.grid_helper_curvelinear import GridHelperCurveLinear\n\ndef curvelinear_test1(fig):\n    # Define custom transform\n    def tr(x, y):\n        return x, y - x\n    def inv_tr(x, y):\n        return x, y + x\n\n    # Create GridHelperCurveLinear object\n    grid_helper = GridHelperCurveLinear((tr, inv_tr))\n\n    # Create a subplot with the custom grid and tick lines\n    ax1 = fig.add_subplot(1, 2, 1, axes_class=Axes, grid_helper=grid_helper)\n\n    # Plot some points on the subplot\n    xx, yy = tr(np.array([3, 6]), np.array([5, 10]))\n    ax1.plot(xx, yy)\n\n    # Set the aspect ratio and limits of the subplot\n    ax1.set_aspect(1)\n    ax1.set_xlim(0, 10)\n    ax1.set_ylim(0, 10)\n\n    # Add floating axes and grid lines\n    ax1.axis[\"t\"] = ax1.new_floating_axis(0, 3)\n    ax1.axis[\"t2\"] = ax1.new_floating_axis(1, 7)\n    ax1.grid(True, zorder=0)\n\ndef curvelinear_test2(fig):\n    # Define the custom transform\n    tr = Affine2D().scale(np.pi/180, 1) + PolarAxes.PolarTransform()\n\n    # Define the extreme finder, grid locator, and tick formatter\n    extreme_finder = angle_helper.ExtremeFinderCycle(\n        nx=20, ny=20,\n        lon_cycle=360, lat_cycle=None,\n        lon_minmax=None, lat_minmax=(0, np.inf),\n    )\n    grid_locator1 = angle_helper.LocatorDMS(12)\n    tick_formatter1 = angle_helper.FormatterDMS()\n\n    # Create GridHelperCurveLinear object"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-custom-grid-transformation-with-matplotlib":{"intro":"This lab provides a step-by-step guide on how to use GridHelperCurveLinear to define custom grids and ticklines by applying a transformation on the grid. We will use Python's Matplotlib library to create custom grids and ticklines.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries, including matplotlib.pyplot, numpy, ExtremeFinderSimple, MaxNLocator, and GridHelperCurveLinear."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom mpl_toolkits.axisartist.axislines import Axes\nfrom mpl_toolkits.axisartist.grid_finder import (ExtremeFinderSimple, MaxNLocator)\nfrom mpl_toolkits.axisartist.grid_helper_curvelinear import GridHelperCurveLinear"}]},{"title":"Define Transformation Functions","body":["Define Transformation Functions","The second step is to define the transformation functions. In this example, we will use the tr function to transform the x-axis values and leave the y-axis values unchanged. The inv_tr function will be used to invert the transformation."],"code":[{"lang":"python","text":"def tr(x, y):\n    return np.sign(x)*abs(x)**.5, y\n\ndef inv_tr(x, y):\n    return np.sign(x)*x**2, y"}]},{"title":"Define GridHelperCurveLinear","body":["The third step is to define the GridHelperCurveLinear instance. We will use the transformation functions defined in Step 2 to transform the grid. We will also set the grid_locator1 and grid_locator2 to MaxNLocator(nbins=6) to increase the tick density."],"code":[{"lang":"python","text":"grid_helper = GridHelperCurveLinear(\n    (tr, inv_tr),\n    extreme_finder=ExtremeFinderSimple(20, 20),\n    grid_locator1=MaxNLocator(nbins=6), grid_locator2=MaxNLocator(nbins=6))"}]},{"title":"Define Axes and Display Image","body":["The fourth step is to define the axes using the grid_helper instance created in Step 3. We will also display an image using the imshow function."],"code":[{"lang":"python","text":"ax1 = fig.add_subplot(axes_class=Axes, grid_helper=grid_helper)\nax1.imshow(np.arange(25).reshape(5, 5), vmax=50, cmap=plt.cm.gray_r, origin=\"lower\")"}]},{"title":"Create the Figure","body":["The final step is to create the figure using the plt.figure function. We will set the figure size to (7, 4) and call the curvelinear_test1 function created in Steps 2-4."],"code":[{"lang":"python","text":"if __name__ == \"__main__\":\n    fig = plt.figure(figsize=(7, 4))\n    curvelinear_test1(fig)\n    plt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"if __name__ == \"__main__\":\n    fig = plt.figure(figsize=(7, 4))\n    curvelinear_test1(fig)\n    plt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-image-grid-colorbars":{"intro":"This lab is about creating image grids with colorbars using Matplotlib. The example code provided shows how to use one common colorbar for each row or column of an image grid.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries to create the image grid with colorbars."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib import cbook\nfrom mpl_toolkits.axes_grid1 import AxesGrid"}]},{"title":"Define Image Data","body":["We define a function that returns a sample image data and its extent."],"code":[{"lang":"python","text":"def get_demo_image():\n    z = cbook.get_sample_data(\"axes_grid/bivariate_normal.npy\")  # 15x15 array\n    return z, (-3, 4, -4, 3)"}]},{"title":"Create a Grid with Bottom Colorbar","body":["Create a Grid with Bottom Colorbar","We create a grid of 2x2 images with a colorbar for each column."],"code":[{"lang":"python","text":"def demo_bottom_cbar(fig):\n    grid = AxesGrid(fig, 121,  # similar to subplot(121)\n                    nrows_ncols=(2, 2),\n                    axes_pad=0.10,\n                    share_all=True,\n                    label_mode=\"1\",\n                    cbar_location=\"bottom\",\n                    cbar_mode=\"edge\",\n                    cbar_pad=0.25,\n                    cbar_size=\"15%\",\n                    direction=\"column\"\n                    )\n\n    Z, extent = get_demo_image()\n    cmaps = [\"autumn\", \"summer\"]\n    for i in range(4):\n        im = grid[i].imshow(Z, extent=extent, cmap=cmaps[i//2])\n        if i % 2:\n            grid.cbar_axes[i//2].colorbar(im)\n\n    for cax in grid.cbar_axes:\n        cax.axis[cax.orientation].set_label(\"Bar\")\n\n    # This affects all axes as share_all = True.\n    grid.axes_llc.set_xticks([-2, 0, 2])\n    grid.axes_llc.set_yticks([-2, 0, 2])"}]},{"title":"Create a Grid with Right Colorbar","body":["Create a Grid with Right Colorbar","We create a grid of 2x2 images with a colorbar for each row."],"code":[{"lang":"python","text":"def demo_right_cbar(fig):\n    grid = AxesGrid(fig, 122,  # similar to subplot(122)\n                    nrows_ncols=(2, 2),\n                    axes_pad=0.10,\n                    label_mode=\"1\",\n                    share_all=True,\n                    cbar_location=\"right\",\n                    cbar_mode=\"edge\",\n                    cbar_size=\"7%\",\n                    cbar_pad=\"2%\",\n                    )\n    Z, extent = get_demo_image()\n    cmaps = [\"spring\", \"winter\"]\n    for i in range(4):\n        im = grid[i].imshow(Z, extent=extent, cmap=cmaps[i//2])\n        if i % 2:\n            grid.cbar_axes[i//2].colorbar(im)\n\n    for cax in grid.cbar_axes:\n        cax.axis[cax.orientation].set_label('Foo')\n\n    # This affects all axes because we set share_all = True.\n    grid.axes_llc.set_xticks([-2, 0, 2])\n    grid.axes_llc.set_yticks([-2, 0, 2])"}]},{"title":"Create the Figure and Call the Functions","body":["Create the Figure and Call the Functions","Finally, we create the figure and call the functions to create the image grids with colorbars."],"code":[{"lang":"python","text":"fig = plt.figure()\n\ndemo_bottom_cbar(fig)\ndemo_right_cbar(fig)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure()\n\ndemo_bottom_cbar(fig)\ndemo_right_cbar(fig)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-fixed-size-axes":{"intro":"In data visualization, it's important to have consistent axes sizes in order to make meaningful comparisons between different plots. The Matplotlib library provides a way to create fixed size axes for figures that do not change size. In this lab, we will learn how to create fixed size axes using Matplotlib.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1 import Divider, Size"}]},{"title":"Create a Figure","body":["Next, we will create a figure with a fixed size using the plt.figure() function."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(6, 6))"}]},{"title":"Define the Sizes of the Axes","body":["We will define the size of the axes using the Size class. In this example, we will create an axes with a fixed physical size of 4.5 inches by 5 inches."],"code":[{"lang":"python","text":"h = [Size.Fixed(1.0), Size.Fixed(4.5)]\nv = [Size.Fixed(0.7), Size.Fixed(5.)]"}]},{"title":"Create a Divider","body":["We will create a Divider object that will divide the figure into the specified sizes."],"code":[{"lang":"python","text":"divider = Divider(fig, (0, 0, 1, 1), h, v, aspect=False)"}]},{"title":"Add Axes to the Figure","body":["We will add the axes to the figure using the add_axes() function and passing in the position of the Divider object."],"code":[{"lang":"python","text":"ax = fig.add_axes(divider.get_position(),\n                  axes_locator=divider.new_locator(nx=1, ny=1))"}]},{"title":"Plot Data","body":["We will plot some data on the axes using the plot() function."],"code":[{"lang":"python","text":"ax.plot([1, 2, 3])"}]},{"title":"Show the Plot","body":["Finally, we will show the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-floating-axes":{"intro":"In this lab, we will learn how to use the floating_axes module of Matplotlib to create custom plots with non-rectangular shapes. This module is useful when we need to plot data on non-Cartesian coordinate systems, such as polar or logarithmic plots. We will demonstrate how to create a scatter plot, a bar plot, and a sector plot using different coordinate systems.","steps":[{"title":"Importing necessary libraries","body":["First, we need to import the necessary libraries. We will use Matplotlib, NumPy, and some modules from mpl_toolkits.axisartist and mpl_toolkits.axisartist.grid_finder."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.projections import PolarAxes\nfrom matplotlib.transforms import Affine2D\nimport mpl_toolkits.axisartist.angle_helper as angle_helper\nimport mpl_toolkits.axisartist.floating_axes as floating_axes\nfrom mpl_toolkits.axisartist.grid_finder import (DictFormatter, FixedLocator,\n                                                 MaxNLocator)"}]},{"title":"Creating a simple floating axes plot","body":["Creating a simple floating axes plot","In this step, we will create a simple floating axes plot using GridHelperCurveLinear. We will create a scatter plot and a bar plot with a non-rectangular shape."],"code":[{"lang":"python","text":"def setup_axes1(fig, rect):\n    tr = Affine2D().scale(2, 1).rotate_deg(30)\n\n    grid_helper = floating_axes.GridHelperCurveLinear(\n        tr, extremes=(-0.5, 3.5, 0, 4),\n        grid_locator1=MaxNLocator(nbins=4),\n        grid_locator2=MaxNLocator(nbins=4))\n\n    ax1 = fig.add_subplot(\n        rect, axes_class=floating_axes.FloatingAxes, grid_helper=grid_helper)\n    ax1.grid()\n\n    aux_ax = ax1.get_aux_axes(tr)\n\n    return ax1, aux_ax\n\nfig = plt.figure(figsize=(8, 4))\nfig.subplots_adjust(wspace=0.3, left=0.05, right=0.95)\n\nax1, aux_ax1 = setup_axes1(fig, 131)\naux_ax1.bar([0, 1, 2, 3], [3, 2, 1, 3])"}]},{"title":"Creating a polar plot","body":["In this step, we will create a polar plot using GridHelperCurveLinear. We will create a scatter plot with a non-rectangular shape."],"code":[{"lang":"python","text":"def setup_axes2(fig, rect):\n    tr = PolarAxes.PolarTransform()\n\n    pi = np.pi\n    angle_ticks = [(0, r\"$0$\"),\n                   (.25*pi, r\"$\\frac{1}{4}\\pi$\"),\n                   (.5*pi, r\"$\\frac{1}{2}\\pi$\")]\n    grid_locator1 = FixedLocator([v for v, s in angle_ticks])\n    tick_formatter1 = DictFormatter(dict(angle_ticks))\n\n    grid_locator2 = MaxNLocator(2)\n\n    grid_helper = floating_axes.GridHelperCurveLinear(\n        tr, extremes=(.5*pi, 0, 2, 1),\n        grid_locator1=grid_locator1,\n        grid_locator2=grid_locator2,\n        tick_formatter1=tick_formatter1,\n        tick_formatter2=None)\n\n    ax1 = fig.add_subplot(\n        rect, axes_class=floating_axes.FloatingAxes, grid_helper=grid_helper)\n    ax1.grid()\n\n    aux_ax = ax1.get_aux_axes(tr)\n\n    aux_ax.patch = ax1.patch\n    ax1.patch.zorder = 0.9\n\n    return ax1, aux_ax\n\nax2, aux_ax2 = setup_axes2(fig, 132)\ntheta = np.random.rand(10)*.5*np.pi\nradius = np.random.rand(10) + 1.\naux_ax2.scatter(theta, radius)"}]},{"title":"Creating a sector plot","body":["In this step, we will create a sector plot using GridHelperCurveLinear. We will create a scatter plot with a non-rectangular shape."],"code":[{"lang":"python","text":"def setup_axes3(fig, rect):\n    tr_rotate = Affine2D().translate(-95, 0)\n    tr_scale = Affine2D().scale(np.pi/180., 1.)\n    tr = tr_rotate + tr_scale + PolarAxes.PolarTransform()\n\n    grid_locator1 = angle_helper.LocatorHMS(4)\n    tick_formatter1 = angle_helper.FormatterHMS()\n\n    grid_locator2 = MaxNLocator(3)\n\n    ra0, ra1 = 8.*15, 14.*15\n    cz0, cz1 = 0, 14000\n    grid_helper = floating_axes.GridHelperCurveLinear(\n        tr, extremes=(ra0, ra1, cz0, cz1),\n        grid_locator1=grid_locator1,\n        grid_locator2=grid_locator2,\n        tick_formatter1=tick_formatter1,\n        tick_formatter2=None)\n\n    ax1 = fig.add_subplot(\n        rect, axes_class=floating_axes.FloatingAxes, grid_helper=grid_helper)\n\n    ax1.axis[\"left\"].set_axis_direction(\"bottom\")\n    ax1.axis[\"right\"].set_axis_direction(\"top\")\n\n    ax1.axis[\"bottom\"].set_visible(False)\n    ax1.axis[\"top\"].set_axis_direction(\"bottom\")\n    ax1.axis[\"top\"].toggle(ticklabels=True, label=True)\n    ax1.axis[\"top\"].major_ticklabels.set_axis_direction(\"top\")\n    ax1.axis[\"top\"].label.set_axis_direction(\"top\")\n\n    ax1.axis[\"left\"].label.set_text(r\"cz [km$^{-1}$]\")\n    ax1.axis[\"top\"].label.set_text(r\"$\\alpha_{1950}$\")\n    ax1.grid()\n\n    aux_ax = ax1.get_aux_axes(tr)\n\n    aux_ax.patch = ax1.patch\n    ax1.patch.zorder = 0.9\n\n    return ax1, aux_ax\n\nax3, aux_ax3 = setup_axes3(fig, 133)\ntheta = (8 + np.random.rand(10)*(14 - 8))*15.\nradius = np.random.rand(10)*14000.\naux_ax3.scatter(theta, radius)"}]},{"title":"Displaying the plot","body":["Finally, we need to display the plot using the show() function of Matplotlib."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-polar-plots-with-matplotlib":{"intro":"Matplotlib is a Python library used for creating static, animated, and interactive visualizations in Python. One of the key features of Matplotlib is its ability to create 2D and 3D plots of all types and styles, including scatter plots, line plots, and bar charts. In this lab, you will learn how to create a polar curve in a rectangular box using Matplotlib.","steps":[{"title":"Import Required Libraries","body":["In this step, we will import the required libraries for creating the polar curve. We will use numpy for numerical computing and matplotlib for creating the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Polar Axes","body":["In this step, we will define the polar axes and set the scaling factor. We will use PolarAxes.PolarTransform() to define the polar axes."],"code":[{"lang":"python","text":"from matplotlib.projections import PolarAxes\nfrom matplotlib.transforms import Affine2D\n\n# Define the polar axes\ntr = Affine2D().scale(np.pi / 180., 1.) + PolarAxes.PolarTransform()"}]},{"title":"Define the Grid Helper","body":["In this step, we will define the grid helper that will be used to create the polar curve. We will use GridHelperCurveLinear to define the grid helper."],"code":[{"lang":"python","text":"from mpl_toolkits.axisartist import GridHelperCurveLinear, HostAxes\nimport mpl_toolkits.axisartist.angle_helper as angle_helper\n\n# Define the grid helper\nextreme_finder = angle_helper.ExtremeFinderCycle(20,\n                                                 20,\n                                                 lon_cycle=360,\n                                                 lat_cycle=None,\n                                                 lon_minmax=None,\n                                                 lat_minmax=(0, np.inf),\n                                                 )\ngrid_locator1 = angle_helper.LocatorDMS(12)\ntick_formatter1 = angle_helper.FormatterDMS()\n\ngrid_helper = GridHelperCurveLinear(tr,\n                                    extreme_finder=extreme_finder,\n                                    grid_locator1=grid_locator1,\n                                    tick_formatter1=tick_formatter1\n                                    )"}]},{"title":"Create the Host Axes","body":["In this step, we will create the host axes and set the grid helper. We will use fig.add_subplot() to create the host axes."],"code":[{"lang":"python","text":"# Create the host axes\nfig = plt.figure(figsize=(5, 5))\nax1 = fig.add_subplot(axes_class=HostAxes, grid_helper=grid_helper)"}]},{"title":"Create Floating Axes","body":["In this step, we will create two floating axes that will be used to display the polar curve in a rectangular box. We will use new_floating_axis() to create the floating axes."],"code":[{"lang":"python","text":"# Create the floating axes\nax1.axis[\"lat\"] = axis = ax1.new_floating_axis(0, 60)\naxis.label.set_text(r\"$\\theta = 60^{\\circ}$\")\naxis.label.set_visible(True)\n\nax1.axis[\"lon\"] = axis = ax1.new_floating_axis(1, 6)\naxis.label.set_text(r\"$r = 6$\")"}]},{"title":"Set the Limits and Display the Grid","body":["Set the Limits and Display the Grid","In this step, we will set the limits for the axes and display the grid. We will use set_aspect() to set the aspect ratio of the axes and grid() to display the grid."],"code":[{"lang":"python","text":"# Set the limits and display the grid\nax1.set_aspect(1.)\nax1.set_xlim(-5, 12)\nax1.set_ylim(-5, 10)\nax1.grid(True)"}]},{"title":"Display the Polar Curve","body":["In this step, we will display the polar curve in the rectangular box. We will use plt.show() to display the plot."],"code":[{"lang":"python","text":"# Display the polar curve\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Display the polar curve\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-subplot-generation-tutorial":{"intro":"In this tutorial, you will learn how to use the subplot2grid function in Python's Matplotlib library to generate subplots.","steps":[{"title":"Import Required Libraries","body":["Before we start, we need to import the Matplotlib library using the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create a Figure Object","body":["To create a figure object, use the following code:"],"code":[{"lang":"python","text":"fig = plt.figure()"}]},{"title":"Define Subplots Using subplot2grid","body":["Define Subplots Using subplot2grid","To define subplots using subplot2grid, we first need to specify the size of the grid using a tuple with the desired number of rows and columns. We also need to specify the location of the subplot within the grid using another tuple.","For example, to create a 3x3 grid with a subplot that spans the entire first row and all three columns, we use the following code:","To create a subplot that spans the second row and first two columns, we use:"],"code":[{"lang":"python","text":"ax1 = plt.subplot2grid((3, 3), (0, 0), colspan=3)"},{"lang":"python","text":"ax2 = plt.subplot2grid((3, 3), (1, 0), colspan=2)"},{"lang":"python","text":"ax3 = plt.subplot2grid((3, 3), (1, 2), rowspan=2)"}]},{"title":"Annotate Axes","body":["To annotate the axes, we can loop through the figure axes and add text using the text function and the tick_params function to remove the tick labels."],"code":[{"lang":"python","text":"def annotate_axes(fig):\n    for i, ax in enumerate(fig.axes):\n        ax.text(0.5, 0.5, \"ax%d\" % (i+1), va=\"center\", ha=\"center\")\n        ax.tick_params(labelbottom=False, labelleft=False)"}]},{"title":"Display the Plot","body":["To display the plot, use the following code:"],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-subplot-customization-with-gridspec":{"intro":"In this tutorial, we will learn how to use GridSpec to generate subplots, control the relative sizes of subplots with _width_ratios_ and _height_ratios_, and the spacing around and between subplots using subplot params (_left_, _right_, _bottom_, _top_, _wspace_, and _hspace_).","steps":[{"title":"Import Libraries","body":["We start by importing the necessary libraries, which are matplotlib.pyplot and GridSpec."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.gridspec import GridSpec"}]},{"title":"Generate Subplots with GridSpec","body":["Generate Subplots with GridSpec","In this step, we will use GridSpec to generate subplots. We will create a figure with 2 rows and 2 columns. We will also specify the width_ratios and height_ratios to control the relative sizes of the subplots."],"code":[{"lang":"python","text":"fig = plt.figure()\ngs = GridSpec(2, 2, width_ratios=[1, 2], height_ratios=[4, 1])\nax1 = fig.add_subplot(gs[0])\nax2 = fig.add_subplot(gs[1])\nax3 = fig.add_subplot(gs[2])\nax4 = fig.add_subplot(gs[3])"}]},{"title":"Control Spacing Around and Between Subplots","body":["Control Spacing Around and Between Subplots","In this step, we will use GridSpec to control the spacing around and between subplots. We will create a figure with 2 gridspecs, each with 3 rows and 3 columns. We will specify the left, right, bottom, top, wspace, and hspace parameters to control the spacing."],"code":[{"lang":"python","text":"fig = plt.figure()\ngs1 = GridSpec(3, 3, left=0.05, right=0.48, wspace=0.05)\nax1 = fig.add_subplot(gs1[:-1, :])\nax2 = fig.add_subplot(gs1[-1, :-1])\nax3 = fig.add_subplot(gs1[-1, -1])\n\ngs2 = GridSpec(3, 3, left=0.55, right=0.98, hspace=0.05)\nax4 = fig.add_subplot(gs2[:, :-1])\nax5 = fig.add_subplot(gs2[:-1, -1])\nax6 = fig.add_subplot(gs2[-1, -1])"}]},{"title":"Annotate Axes","body":["In this step, we will annotate the axes with their corresponding subplot numbers."],"code":[{"lang":"python","text":"def annotate_axes(fig):\n    for i, ax in enumerate(fig.axes):\n        ax.text(0.5, 0.5, \"ax%d\" % (i+1), va=\"center\", ha=\"center\")\n        ax.tick_params(labelbottom=False, labelleft=False)\n\nannotate_axes(fig)"}]},{"title":"Display the Plots","body":["In this step, we will display the plots."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-nested-gridspecs":{"intro":"In this lab, you will learn how to use nested .GridSpecs in Matplotlib to create a grid of subplots with varying sizes. This is useful when you want to create a complex layout of plots and have control over the size and spacing of each plot.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will be using matplotlib.pyplot for creating the plots and numpy for generating some data to plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Data","body":["In this step, we will create some data to plot. We will use the squiggle_xy function to generate some sine and cosine waves with different frequencies."],"code":[{"lang":"python","text":"def squiggle_xy(a, b, c, d):\n    i = np.arange(0.0, 2*np.pi, 0.05)\n    return np.sin(i*a)*np.cos(i*b), np.sin(i*c)*np.cos(i*d)"}]},{"title":"Create the Figure and Outer Grid","body":["Create the Figure and Outer Grid","Next, we will create the figure and the outer grid using the add_gridspec function. We will create a 4x4 grid with no spacing between the subplots."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(8, 8))\nouter_grid = fig.add_gridspec(4, 4, wspace=0, hspace=0)"}]},{"title":"Create the Inner Grids and Subplots","body":["Create the Inner Grids and Subplots","In this step, we will create the inner grids and subplots using nested .GridSpecs. We will loop through each cell in the outer grid and create a 3x3 grid for each cell."],"code":[{"lang":"python","text":"for a in range(4):\n    for b in range(4):\n        # gridspec inside gridspec\n        inner_grid = outer_grid[a, b].subgridspec(3, 3, wspace=0, hspace=0)\n        axs = inner_grid.subplots()  # Create all subplots for the inner grid.\n        for (c, d), ax in np.ndenumerate(axs):\n            ax.plot(*squiggle_xy(a + 1, b + 1, c + 1, d + 1))\n            ax.set(xticks=[], yticks=[])"}]},{"title":"Show Only the Outer Spines","body":["In this step, we will remove the spines for the inner subplots and only show the outer spines. This will make the plot look cleaner."],"code":[{"lang":"python","text":"for ax in fig.get_axes():\n    ss = ax.get_subplotspec()\n    ax.spines.top.set_visible(ss.is_first_row())\n    ax.spines.bottom.set_visible(ss.is_last_row())\n    ax.spines.left.set_visible(ss.is_first_col())\n    ax.spines.right.set_visible(ss.is_last_col())"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-image-grid-visualization":{"intro":"Matplotlib is a data visualization library in Python used to create static, animated, and interactive visualizations. In this tutorial, we will explore how to use the Matplotlib ImageGrid to display a collection of images in a grid format with fixed aspect ratios.","steps":[{"title":"Import required libraries","body":["First, we need to import the required libraries. In this example, we need the matplotlib.pyplot and mpl_toolkits.axes_grid1.ImageGrid libraries."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axes_grid1 import ImageGrid"}]},{"title":"Create a figure object","body":["Next, we create a figure object using the plt.figure() function."],"code":[{"lang":"python","text":"fig = plt.figure()"}]},{"title":"Create the ImageGrids","body":["We will create two ImageGrids to display our images. The first ImageGrid will have two rows and two columns, and the second ImageGrid will also have two rows and two columns."],"code":[{"lang":"python","text":"grid1 = ImageGrid(fig, 121, (2, 2), axes_pad=0.1, aspect=True, share_all=True)\ngrid2 = ImageGrid(fig, 122, (2, 2), axes_pad=0.1, aspect=True, share_all=True)"}]},{"title":"Set the aspect ratio","body":["We will set the aspect ratio of the cells in the ImageGrids to 2 using the set_aspect() function."],"code":[{"lang":"python","text":"for i in [0, 1]:\n    grid1[i].set_aspect(2)\n\nfor i in [1, 3]:\n    grid2[i].set_aspect(2)"}]},{"title":"Display the ImageGrids","body":["Finally, we use the plt.show() function to display our ImageGrids."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-demo-parasite-axes":{"intro":"In this lab, you will learn how to create a parasite axes using the mpl_toolkits.axes_grid1.parasite_axes.HostAxes and mpl_toolkits.axes_grid1.parasite_axes.ParasiteAxes modules in Matplotlib. The parasite axes shares the x-scale with a host axes, but shows a different scale in y direction.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries. In this lab, we will be using matplotlib.pyplot for plotting, mpl_toolkits.axes_grid1.parasite_axes.HostAxes and mpl_toolkits.axes_grid1.parasite_axes.ParasiteAxes for creating a parasite axes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits.axisartist.parasite_axes import HostAxes"}]},{"title":"Create a figure and add host axes","body":["Create a figure and add host axes","We create a figure using plt.figure() method and add a host axes using fig.add_axes() method. Host axes shares the x-scale with parasite axes."],"code":[{"lang":"python","text":"fig = plt.figure()\nhost = fig.add_axes([0.15, 0.1, 0.65, 0.8], axes_class=HostAxes)"}]},{"title":"Create parasite axes","body":["We create two parasite axes using host.get_aux_axes() method. We set viewlim_mode=None to ensure that the parasite axes share the same x-scale with the host axes. We also set sharex=host to ensure that the x-scale is shared."],"code":[{"lang":"python","text":"par1 = host.get_aux_axes(viewlim_mode=None, sharex=host)\npar2 = host.get_aux_axes(viewlim_mode=None, sharex=host)"}]},{"title":"Hide right y-axis of host axes","body":["Hide right y-axis of host axes","We hide the right y-axis of the host axes using host.axis[\"right\"].set_visible(False) method."],"code":[{"lang":"python","text":"host.axis[\"right\"].set_visible(False)"}]},{"title":"Show right y-axis of parasite axes 1","body":["Show right y-axis of parasite axes 1","We show the right y-axis of the first parasite axes using par1.axis[\"right\"].set_visible(True) method. We also set par1.axis[\"right\"].major_ticklabels.set_visible(True) and par1.axis[\"right\"].label.set_visible(True) to show the tick labels and label of the right y-axis."],"code":[{"lang":"python","text":"par1.axis[\"right\"].set_visible(True)\npar1.axis[\"right\"].major_ticklabels.set_visible(True)\npar1.axis[\"right\"].label.set_visible(True)"}]},{"title":"Add right y-axis to parasite axes 2","body":["Add right y-axis to parasite axes 2","We add a right y-axis to the second parasite axes using par2.axis[\"right2\"] = par2.new_fixed_axis(loc=\"right\", offset=(60, 0)) method."],"code":[{"lang":"python","text":"par2.axis[\"right2\"] = par2.new_fixed_axis(loc=\"right\", offset=(60, 0))"}]},{"title":"Plot data on all axes","body":["We plot data on all axes using plot() method. We also set labels and limits for all axes using set() method."],"code":[{"lang":"python","text":"p1, = host.plot([0, 1, 2], [0, 1, 2], label=\"Density\")\np2, = par1.plot([0, 1, 2], [0, 3, 2], label=\"Temperature\")\np3, = par2.plot([0, 1, 2], [50, 30, 15], label=\"Velocity\")\n\nhost.set(xlim=(0, 2), ylim=(0, 2), xlabel=\"Distance\", ylabel=\"Density\")\npar1.set(ylim=(0, 4), ylabel=\"Temperature\")\npar2.set(ylim=(1, 65), ylabel=\"Velocity\")"}]},{"title":"Add legend and axis colors","body":["We add a legend to the host axes using host.legend() method. We also set the color of the left y-axis label of the host axes, the right y-axis label of the first parasite axes, and the right y-axis label of the second parasite axes to match their respective lines using host.axis[\"left\"].label.set_color(p1.get_color()), par1.axis[\"right\"].label.set_color(p2.get_color()), and par2.axis[\"right2\"].label.set_color(p3.get_color()) methods."],"code":[{"lang":"python","text":"host.legend()\n\nhost.axis[\"left\"].label.set_color(p1.get_color())\npar1.axis[\"right\"].label.set_color(p2.get_color())\npar2.axis[\"right2\"].label.set_color(p3.get_color())"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-create-multiplot-with-parasite-axes-in-matpl":{"intro":"In this lab, we will learn how to create a multiple dataset plot using parasite axis in Python Matplotlib. We will use the mpl_toolkits.axes_grid1.parasite_axes.host_subplot and mpl_toolkits.axisartist.axislines.Axes to create a plot with multiple y-axes.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries. We will use matplotlib.pyplot for plotting and mpl_toolkits for creating parasite axis."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom mpl_toolkits import axisartist\nfrom mpl_toolkits.axes_grid1 import host_subplot"}]},{"title":"Create Host and Parasite Axes","body":["We will create a host axis and two parasite axes using the host_subplot() and twinx() functions. The host_subplot() function creates a host axis, and the twinx() function creates parasite axes that share the same x-axis with the host axis."],"code":[{"lang":"python","text":"host = host_subplot(111, axes_class=axisartist.Axes)\nplt.subplots_adjust(right=0.75)\n\npar1 = host.twinx()\npar2 = host.twinx()"}]},{"title":"Adjust Parasite Axis","body":["We need to adjust the position of the parasite axes. The new_fixed_axis() function is used to create a new y-axis on the right side of the plot. The toggle() function is used to turn on all the ticks and labels of the right y-axis."],"code":[{"lang":"python","text":"par2.axis[\"right\"] = par2.new_fixed_axis(loc=\"right\", offset=(60, 0))\n\npar1.axis[\"right\"].toggle(all=True)\npar2.axis[\"right\"].toggle(all=True)"}]},{"title":"Plot the Data","body":["We will plot three datasets on the same plot: Density, Temperature, and Velocity. We will use the plot() function to plot the data."],"code":[{"lang":"python","text":"p1, = host.plot([0, 1, 2], [0, 1, 2], label=\"Density\")\np2, = par1.plot([0, 1, 2], [0, 3, 2], label=\"Temperature\")\np3, = par2.plot([0, 1, 2], [50, 30, 15], label=\"Velocity\")"}]},{"title":"Set Axis Limits and Labels","body":["We will set the x-axis and y-axis limits and labels for each axis using the set() function."],"code":[{"lang":"python","text":"host.set(xlim=(0, 2), ylim=(0, 2), xlabel=\"Distance\", ylabel=\"Density\")\npar1.set(ylim=(0, 4), ylabel=\"Temperature\")\npar2.set(ylim=(1, 65), ylabel=\"Velocity\")"}]},{"title":"Add Legend and Color","body":["We will add a legend to the plot and color the labels of each axis to match the color of the corresponding dataset using the legend() and label.set_color() functions."],"code":[{"lang":"python","text":"host.legend()\n\nhost.axis[\"left\"].label.set_color(p1.get_color())\npar1.axis[\"right\"].label.set_color(p2.get_color())\npar2.axis[\"right\"].label.set_color(p3.get_color())"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-ribbon-box":{"intro":"Matplotlib is a popular data visualization library for Python. This tutorial will guide you through creating a ribbon box chart, a unique way to visualize data. A ribbon box chart is a stacked bar chart where each bar is 'ribbon-like' and has a gradient color scheme.","steps":[{"title":"Importing libraries and loading data","body":["Importing libraries and loading data","In this step, we will import the necessary libraries and load the data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib import cbook\nfrom matplotlib import colors as mcolors\nfrom matplotlib.image import AxesImage\nfrom matplotlib.transforms import Bbox, BboxTransformTo, TransformedBbox"}]},{"title":"Creating the RibbonBox class","body":["In this step, we will create the RibbonBox class that will be used to create the gradient colors for the ribbon boxes."],"code":[{"lang":"python","text":"class RibbonBox:\n    # Load the ribbon box image\n    original_image = plt.imread(cbook.get_sample_data(\"Minduka_Present_Blue_Pack.png\"))\n    cut_location = 70\n    b_and_h = original_image[:, :, 2:3]\n    color = original_image[:, :, 2:3] - original_image[:, :, 0:1]\n    alpha = original_image[:, :, 3:4]\n    nx = original_image.shape[1]\n\n    def __init__(self, color):\n        rgb = mcolors.to_rgb(color)\n        self.im = np.dstack([self.b_and_h - self.color * (1 - np.array(rgb)), self.alpha])\n\n    def get_stretched_image(self, stretch_factor):\n        stretch_factor = max(stretch_factor, 1)\n        ny, nx, nch = self.im.shape\n        ny2 = int(ny*stretch_factor)\n        return np.vstack([self.im[:self.cut_location],\n                          np.broadcast_to(self.im[self.cut_location], (ny2 - ny, nx, nch)),\n                          self.im[self.cut_location:]])"}]},{"title":"Creating the RibbonBoxImage class","body":["Creating the RibbonBoxImage class","In this step, we will create the RibbonBoxImage class that will be used to create the actual ribbon boxes."],"code":[{"lang":"python","text":"class RibbonBoxImage(AxesImage):\n    zorder = 1\n\n    def __init__(self, ax, bbox, color, *, extent=(0, 1, 0, 1), **kwargs):\n        super().__init__(ax, extent=extent, **kwargs)\n        self._bbox = bbox\n        self._ribbonbox = RibbonBox(color)\n        self.set_transform(BboxTransformTo(bbox))\n\n    def draw(self, renderer, *args, **kwargs):\n        stretch_factor = self._bbox.height / self._bbox.width\n\n        ny = int(stretch_factor*self._ribbonbox.nx)\n        if self.get_array() is None or self.get_array().shape[0] != ny:\n            arr = self._ribbonbox.get_stretched_image(stretch_factor)\n            self.set_array(arr)\n\n        super().draw(renderer, *args, **kwargs)"}]},{"title":"Creating the chart","body":["In this step, we will create the actual chart by using the RibbonBoxImage class to create the ribbon boxes."],"code":[{"lang":"python","text":"def main():\n    fig, ax = plt.subplots()\n\n    years = np.arange(2004, 2009)\n    heights = [7900, 8100, 7900, 6900, 2800]\n    box_colors = [(0.8, 0.2, 0.2),\n                  (0.2, 0.8, 0.2),\n                  (0.2, 0.2, 0.8),\n                  (0.7, 0.5, 0.8),\n                  (0.3, 0.8, 0.7)]\n\n    for year, h, bc in zip(years, heights, box_colors):\n        bbox0 = Bbox.from_extents(year - 0.4, 0., year + 0.4, h)\n        bbox = TransformedBbox(bbox0, ax.transData)\n        ax.add_artist(RibbonBoxImage(ax, bbox, bc, interpolation=\"bicubic\"))\n        ax.annotate(str(h), (year, h), va=\"bottom\", ha=\"center\")\n\n    ax.set_xlim(years[0] - 0.5, years[-1] + 0.5)\n    ax.set_ylim(0, 10000)\n\n    # Create a background gradient\n    background_gradient = np.zeros((2, 2, 4))\n    background_gradient[:, :, :3] = [1, 1, 0]\n    background_gradient[:, :, 3] = [[0.1, 0.3], [0.3, 0.5]]\n    ax.imshow(background_gradient, interpolation=\"bicubic\", zorder=0.1,\n              extent=(0, 1, 0, 1), transform=ax.transAxes, aspect=\"auto\")\n\n    plt.show()\n\nmain()"}]},{"title":"Understanding the chart","body":["In this step, we will discuss the chart that we have created. The chart consists of ribbon boxes stacked on top of each other to form a bar chart. The height of each ribbon box corresponds to a value in the dataset. The ribbon boxes have a gradient color scheme that makes them visually appealing."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-customizing-text-paths-with-matplotlib":{"intro":"The Matplotlib TextPath is a module that enables the creation of a path that outlines the characters of a text. The resulting path can be used for several purposes, such as a clip path for an image. In this lab, you will learn how to use the TextPath module to create and customize text paths for images.","steps":[{"title":"Install Matplotlib","body":[],"code":[{"lang":"shell","text":"pip install matplotlib"}]},{"title":"Import Required Libraries","body":["First, import the required libraries to create the TextPath."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.cbook import get_sample_data\nfrom matplotlib.image import BboxImage\nfrom matplotlib.offsetbox import (AnchoredOffsetbox, AnnotationBbox, AuxTransformBox)\nfrom matplotlib.patches import PathPatch, Shadow\nfrom matplotlib.text import TextPath\nfrom matplotlib.transforms import IdentityTransform"}]},{"title":"Create a PathClippedImagePatch","body":["Create a PathClippedImagePatch","Create a PathClippedImagePatch object to draw an image of a text path. Use the following code to create a PathClippedImagePatch object:"],"code":[{"lang":"python","text":"class PathClippedImagePatch(PathPatch):\n    def __init__(self, path, bbox_image, **kwargs):\n        super().__init__(path, **kwargs)\n        self.bbox_image = BboxImage(\n            self.get_window_extent, norm=None, origin=None)\n        self.bbox_image.set_data(bbox_image)\n\n    def set_facecolor(self, color):\n        super().set_facecolor(\"none\")\n\n    def draw(self, renderer=None):\n        self.bbox_image.set_clip_path(self._path, self.get_transform())\n        self.bbox_image.draw(renderer)\n        super().draw(renderer)"}]},{"title":"Create an Offset Box","body":["Create an offset box using AuxTransformBox to add the PathClippedImagePatch object. Use the following code to create the offset box:"],"code":[{"lang":"python","text":"offsetbox = AuxTransformBox(IdentityTransform())\noffsetbox.add_artist(p)"}]},{"title":"Create an Anchored Offset Box","body":["Create an anchored offset box using AnnotationBbox to add the offset box and set its position. Use the following code to create the anchored offset box:"],"code":[{"lang":"python","text":"ao = AnchoredOffsetbox(loc='upper left', child=offsetbox, frameon=True,\n                           borderpad=0.2)\nax1.add_artist(ao)"}]},{"title":"Add Another Text","body":["Add another text to the image using PathPatch. Use the following code to add another text:"],"code":[{"lang":"python","text":"for usetex, ypos, string in [\n            (False, 0.25, r\"textpath supports mathtext\"),\n            (True, 0.05, r\"textpath supports \\TeX\"),\n    ]:\n        text_path = TextPath((0, 0), string, size=20, usetex=usetex)\n\n        p1 = PathPatch(text_path, ec=\"w\", lw=3, fc=\"w\", alpha=0.9)\n        p2 = PathPatch(text_path, ec=\"none\", fc=\"k\")\n\n        offsetbox2 = AuxTransformBox(IdentityTransform())\n        offsetbox2.add_artist(p1)\n        offsetbox2.add_artist(p2)\n\n        ab = AnnotationBbox(offsetbox2, (0.95, ypos),\n                            xycoords='axes fraction',\n                            boxcoords=\"offset points\",\n                            box_alignment=(1., 0.),\n                            frameon=False,\n                            )\n        ax1.add_artist(ab)"}]},{"title":"Show the Image","body":["Show the final image using the following code:"],"code":[{"lang":"python","text":"ax1.imshow([[0, 1, 2], [1, 2, 3]], cmap=plt.cm.gist_gray_r,\n               interpolation=\"bilinear\", aspect=\"auto\")\nplt.show()"}]}],"commands":["pip install matplotlib"],"reference":[{"path":"reference.py","text":"ax1.imshow([[0, 1, 2], [1, 2, 3]], cmap=plt.cm.gist_gray_r,\n               interpolation=\"bilinear\", aspect=\"auto\")\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-text-rotation":{"intro":"In this lab, you will learn how to rotate text in Matplotlib using the rotation_mode parameter. The rotation_mode parameter determines the order of rotation and alignment of the text. There are two modes available: default and anchor.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","First, we need to import the necessary libraries. In this lab, we will use Matplotlib to create the plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Define the test_rotation_mode function","body":["Define the test_rotation_mode function","We will create a function called test_rotation_mode that will create subplots to test the different rotation modes. It takes two parameters: fig and mode."],"code":[{"lang":"python","text":"def test_rotation_mode(fig, mode):"}]},{"title":"Define the horizontal and vertical alignment lists","body":["Define the horizontal and vertical alignment lists","Next, we will define the horizontal and vertical alignment lists that will be used to create the subplots. We will create three elements for each list: \"left\", \"center\", and \"right\" for horizontal alignment, and \"top\", \"center\", and \"bottom\" for vertical alignment."],"code":[{"lang":"python","text":"ha_list = [\"left\", \"center\", \"right\"]\nva_list = [\"top\", \"center\", \"baseline\", \"bottom\"]"}]},{"title":"Create the subplots","body":["Now, we will create the subplots using the subplots function. We will create a grid of subplots with the same aspect ratio, and we will remove the ticks from the x and y axes. We will also add a vertical and horizontal line at the center of each subplot to help visualize the alignment."],"code":[{"lang":"python","text":"axs = fig.subplots(len(va_list), len(ha_list), sharex=True, sharey=True,\n                   subplot_kw=dict(aspect=1),\n                   gridspec_kw=dict(hspace=0, wspace=0))\n\nfor i, va in enumerate(va_list):\n    for j, ha in enumerate(ha_list):\n        ax = axs[i, j]\n        ax.set(xticks=[], yticks=[])\n        ax.axvline(0.5, color=\"skyblue\", zorder=0)\n        ax.axhline(0.5, color=\"skyblue\", zorder=0)\n        ax.plot(0.5, 0.5, color=\"C0\", marker=\"o\", zorder=1)"}]},{"title":"Add text to the subplots","body":["We will add text to each subplot using the text function. We will use the parameters rotation, horizontalalignment, verticalalignment, and rotation_mode to rotate and align the text. We will also use the bbox parameter to highlight the bounding box of the text."],"code":[{"lang":"python","text":"kw = (\n    {} if mode == \"default\" else\n    {\"bbox\": dict(boxstyle=\"square,pad=0.\", ec=\"none\", fc=\"C1\", alpha=0.3)}\n)\n\ntexts = {}\n\nfor i, va in enumerate(va_list):\n    for j, ha in enumerate(ha_list):\n        ax = axs[i, j]\n        tx = ax.text(0.5, 0.5, \"Tpg\",\n                     size=\"x-large\", rotation=40,\n                     horizontalalignment=ha, verticalalignment=va,\n                     rotation_mode=mode, **kw)\n        texts[ax] = tx"}]},{"title":"Highlight the bounding box of the text","body":["Highlight the bounding box of the text","If the rotation_mode is set to 'default', we will highlight the bounding box of the text using a rectangle. We will use the get_window_extent function to get the bounding box and transform it to the data coordinates using the transData attribute."],"code":[{"lang":"python","text":"if mode == \"default\":\n    fig.canvas.draw()\n    for ax, text in texts.items():\n        bb = text.get_window_extent().transformed(ax.transData.inverted())\n        rect = plt.Rectangle((bb.x0, bb.y0), bb.width, bb.height,\n                             facecolor=\"C1\", alpha=0.3, zorder=2)\n        ax.add_patch(rect)"}]},{"title":"Create the subfigures and call the test_rotation_mode function","body":["Create the subfigures and call the test_rotation_mode function","We will create two subfigures and call the test_rotation_mode function with the fig and mode parameters."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(8, 5))\nsubfigs = fig.subfigures(1, 2)\ntest_rotation_mode(subfigs[0], \"default\")\ntest_rotation_mode(subfigs[1], \"anchor\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig = plt.figure(figsize=(8, 5))\nsubfigs = fig.subfigures(1, 2)\ntest_rotation_mode(subfigs[0], \"default\")\ntest_rotation_mode(subfigs[1], \"anchor\")\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-adjusting-matplotlib-tick-label-alignment":{"intro":"In data visualization, tick labels play an important role in conveying information to viewers. Sometimes, we may need to adjust the alignment of tick labels to make them more readable or to avoid overlapping. In this lab, we will learn how to use Matplotlib to adjust the alignment of tick labels.","steps":[{"title":"Import Matplotlib and AxisArtist","body":["Import Matplotlib and AxisArtist","First, we need to import Matplotlib and AxisArtist, which provides additional tools for creating custom axes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport mpl_toolkits.axisartist as axisartist"}]},{"title":"Define a Function for Setting Up Axes","body":["Define a Function for Setting Up Axes","To simplify the code, we can define a function that takes a figure object and a position as input, and returns an axis object with custom tick labels."],"code":[{"lang":"python","text":"def setup_axes(fig, pos):\n    ax = fig.add_subplot(pos, axes_class=axisartist.Axes)\n    ax.set_yticks([0.2, 0.8], labels=[\"short\", \"loooong\"])\n    ax.set_xticks([0.2, 0.8], labels=[r\"$\\frac{1}{2}\\pi$\", r\"$\\pi$\"])\n    return ax"}]},{"title":"Create a Figure and Add Subplots","body":["Create a Figure and Add Subplots","Next, we can create a figure object and add three subplots using the setup_axes function."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(3, 5))\nfig.subplots_adjust(left=0.5, hspace=0.7)\n\nax = setup_axes(fig, 311)\nax.set_ylabel(\"ha=right\")\nax.set_xlabel(\"va=baseline\")\n\nax = setup_axes(fig, 312)\nax.axis[\"left\"].major_ticklabels.set_ha(\"center\")\nax.axis[\"bottom\"].major_ticklabels.set_va(\"top\")\nax.set_ylabel(\"ha=center\")\nax.set_xlabel(\"va=top\")\n\nax = setup_axes(fig, 313)\nax.axis[\"left\"].major_ticklabels.set_ha(\"left\")\nax.axis[\"bottom\"].major_ticklabels.set_va(\"bottom\")\nax.set_ylabel(\"ha=left\")\nax.set_xlabel(\"va=bottom\")"}]},{"title":"Adjust Tick Label Alignment","body":["Finally, we can use the set_ha and set_va methods to adjust the horizontal and vertical alignment of tick labels."],"code":[{"lang":"python","text":"ax.axis[\"left\"].major_ticklabels.set_ha(\"center\")\nax.axis[\"bottom\"].major_ticklabels.set_va(\"top\")"}]},{"title":"Display the Plot","body":["To display the plot, we can use the show method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-matplotlib-ticklabel-direction":{"intro":"This lab will guide you through how to set the direction of tick labels in a Matplotlib plot. You will learn how to customize the direction of tick labels for both the x and y axes.","steps":[{"title":"Import necessary modules","body":["First, we need to import the necessary modules to create our plot. We will be using Matplotlib and AxisArtist from mpl_toolkits."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport mpl_toolkits.axisartist.axislines as axislines"}]},{"title":"Create a function to set up axes","body":["Create a function to set up axes","We will create a function to set up our axes with the desired tick labels."],"code":[{"lang":"python","text":"def setup_axes(fig, pos):\n    ax = fig.add_subplot(pos, axes_class=axislines.Axes)\n    ax.set_yticks([0.2, 0.8])\n    ax.set_xticks([0.2, 0.8])\n    return ax"}]},{"title":"Customize tick label direction","body":["Customize tick label direction","We will create three subplots to demonstrate different ways to customize the direction of tick labels."],"code":[]},{"title":": Tick labels pointing outwards","body":["In this step, we will create a subplot with tick labels pointing outwards."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(6, 3))\nfig.subplots_adjust(bottom=0.2)\n\nax = setup_axes(fig, 131)\nfor axis in ax.axis.values():\n    axis.major_ticks.set_tick_out(True)"}]},{"title":": Customized tick label direction","body":["Customized tick label direction","In this step, we will create a subplot with customized tick label direction."],"code":[{"lang":"python","text":"ax = setup_axes(fig, 132)\nax.axis[\"left\"].set_axis_direction(\"right\")\nax.axis[\"bottom\"].set_axis_direction(\"top\")\nax.axis[\"right\"].set_axis_direction(\"left\")\nax.axis[\"top\"].set_axis_direction(\"bottom\")"}]},{"title":": Tick labels pointing outwards on one side","body":["Tick labels pointing outwards on one side","In this step, we will create a subplot with tick labels pointing outwards on one side."],"code":[{"lang":"python","text":"ax = setup_axes(fig, 133)\nax.axis[\"left\"].set_axis_direction(\"right\")\nax.axis[:].major_ticks.set_tick_out(True)\n\nax.axis[\"left\"].label.set_text(\"Long Label Left\")\nax.axis[\"bottom\"].label.set_text(\"Label Bottom\")\nax.axis[\"right\"].label.set_text(\"Long Label Right\")\nax.axis[\"right\"].label.set_visible(True)\nax.axis[\"left\"].label.set_pad(0)\nax.axis[\"bottom\"].label.set_pad(10)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = setup_axes(fig, 133)\nax.axis[\"left\"].set_axis_direction(\"right\")\nax.axis[:].major_ticks.set_tick_out(True)\n\nax.axis[\"left\"].label.set_text(\"Long Label Left\")\nax.axis[\"bottom\"].label.set_text(\"Label Bottom\")\nax.axis[\"right\"].label.set_text(\"Long Label Right\")\nax.axis[\"right\"].label.set_visible(True)\nax.axis[\"left\"].label.set_pad(0)\nax.axis[\"bottom\"].label.set_pad(10)\n\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-demo-tight-layout":{"intro":"This lab is designed to provide a step-by-step guide for using Matplotlib, a Python library for creating visualizations. Matplotlib is a popular data visualization tool in the scientific and engineering communities. This tutorial will walk you through the process of creating visualizations using Matplotlib.","steps":[{"title":"Importing Matplotlib","body":["Before we can start creating visualizations, we need to import Matplotlib.","Here, we are importing the pyplot module of Matplotlib and aliasing it as plt. This is a common convention in the Matplotlib community."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Creating a Simple Plot","body":["Now that we have imported Matplotlib, we can start creating visualizations. Let's start by creating a simple plot.","Here, we are creating two lists x and y that contain the x and y values for our plot. We then use the plot function to create a line plot of x and y. Finally, we use the show function to display the plot."],"code":[{"lang":"python","text":"x = [1, 2, 3, 4, 5]\ny = [2, 4, 6, 8, 10]\n\nplt.plot(x, y)\nplt.show()"}]},{"title":"Customizing the Plot","body":["Now that we have a basic plot, let's customize it.","Here, we have added some customizations to our plot. We have changed the color of the line to red and added circular markers to each data point. We have also added a title and axis labels to our plot."],"code":[{"lang":"python","text":"x = [1, 2, 3, 4, 5]\ny = [2, 4, 6, 8, 10]\n\nplt.plot(x, y, color='red', marker='o')\nplt.title('My Plot')\nplt.xlabel('X Axis Label')\nplt.ylabel('Y Axis Label')\nplt.show()"}]},{"title":"Creating Multiple Plots","body":["We can also create multiple plots in the same figure.","Here, we are using the subplot function to create two plots side-by-side in the same figure. We pass three arguments to subplot: the number of rows, the number of columns, and the plot number. We then create a plot in each subplot."],"code":[{"lang":"python","text":"x = [1, 2, 3, 4, 5]\ny1 = [2, 4, 6, 8, 10]\ny2 = [1, 3, 5, 7, 9]\n\nplt.subplot(1, 2, 1)\nplt.plot(x, y1)\nplt.title('Plot 1')\n\nplt.subplot(1, 2, 2)\nplt.plot(x, y2)\nplt.title('Plot 2')\n\nplt.show()"}]},{"title":"Saving the Plot","body":["Once we have created a plot, we can save it to a file.","Here, we are using the savefig function to save our plot to a file named my_plot.png."],"code":[{"lang":"python","text":"x = [1, 2, 3, 4, 5]\ny = [2, 4, 6, 8, 10]\n\nplt.plot(x, y)\nplt.title('My Plot')\nplt.xlabel('X Axis Label')\nplt.ylabel('Y Axis Label')\nplt.savefig('my_plot.png')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"x = [1, 2, 3, 4, 5]\ny = [2, 4, 6, 8, 10]\n\nplt.plot(x, y)\nplt.title('My Plot')\nplt.xlabel('X Axis Label')\nplt.ylabel('Y Axis Label')\nplt.savefig('my_plot.png')"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-differences-between-dfrac-and-frac":{"intro":"Matplotlib is a data visualization library in Python. In this tutorial, we will discuss the differences between \\dfrac and \\frac TeX macros when using Mathtex in Matplotlib.","steps":[{"title":"Import Matplotlib","body":["To use Matplotlib, we first need to import it. We will also import numpy to generate some sample data for visualization."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Sample Data","body":["We will create two arrays of sample data to plot."],"code":[{"lang":"python","text":"x = np.linspace(0, 10, 100)\ny = np.sin(x)"}]},{"title":"Create a Figure and Axis","body":["We will create a figure and axis object to plot our data on."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Plot the Data with \\frac","body":["We will plot the data with the \\frac TeX macro and display the resulting plot."],"code":[{"lang":"python","text":"ax.plot(x, y, label=r'$\\frac{sin(x)}{x}$')\nax.legend()\nplt.show()"}]},{"title":"Plot the Data with \\dfrac","body":["We will plot the data with the \\dfrac TeX macro and display the resulting plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.plot(x, y, label=r'$\\dfrac{sin(x)}{x}$')\nax.legend()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.plot(x, y, label=r'$\\dfrac{sin(x)}{x}$')\nax.legend()\nplt.show()"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"},"labex-matplotlib-formatting-currency-plots-with-matplotlib":{"intro":"In this lab, we will learn how to use Matplotlib to format the y-axis labels of a plot to display dollar signs. This is particularly useful when working with financial data or any data that requires currency formatting.","steps":[{"title":"Setting Up Libraries and Creating Sample Data","body":["Setting Up Libraries and Creating Sample Data","In this first step, we will import the necessary libraries and create sample financial data for our plot. We need to import both Matplotlib for visualization and NumPy for data generation.","In the first cell of your notebook, enter and run the following code to import the required libraries:","After running the code (press Shift+Enter), you should see the output:"],"code":[{"lang":"python","text":"# Import necessary libraries\nimport matplotlib.pyplot as plt\nimport numpy as np\n\n# Display plots inline in the notebook\n%matplotlib inline\n\nprint(\"Libraries imported successfully!\")"},{"lang":"text","text":"Libraries imported successfully!"},{"lang":"python","text":"# Set a random seed for reproducibility\nnp.random.seed(42)\n\n# Generate financial data: 30 days of revenue data\ndays = np.arange(1, 31)\ndaily_revenue = np.random.uniform(low=1000, high=5000, size=30)\n\nprint(\"Sample of daily revenue data (first 5 days):\")\nfor i in range(5):\n    print(f\"Day {days[i]}: ${daily_revenue[i]:.2f}\")"}]},{"title":"Creating a Basic Financial Plot","body":["Creating a Basic Financial Plot","Now that we have our data ready, let's create a basic plot to visualize the daily revenue. We'll start with a simple line plot that shows the revenue trend over the 30-day period.","In a new cell in your notebook, add and run the following code:","After running this code, you should see a line plot showing the daily revenue trend. It should look something like this (actual values may vary slightly due to random generation):"],"code":[{"lang":"python","text":"# Create a figure and axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Plot the daily revenue data\nax.plot(days, daily_revenue, marker='o', linestyle='-', color='blue', linewidth=2, markersize=6)\n\n# Add labels and title\nax.set_xlabel('Day', fontsize=12)\nax.set_ylabel('Revenue', fontsize=12)\nax.set_title('Daily Revenue Over 30 Days', fontsize=14, fontweight='bold')\n\n# Add grid for better readability\nax.grid(True, linestyle='--', alpha=0.7)\n\n# Display the plot\nplt.tight_layout()\nplt.show()\n\nprint(\"Basic plot created successfully!\")"}]},{"title":"Formatting Y-Axis Labels with Dollar Signs","body":["Formatting Y-Axis Labels with Dollar Signs","Now that we have our basic plot, let's format the y-axis labels to display dollar signs. This will make our financial data more readable and professionally presented.","To format the tick labels on the y-axis, we'll use Matplotlib's ticker module, which provides various formatting options. Specifically, we'll use the StrMethodFormatter class to create a custom formatter for our y-axis.","In a new cell in your notebook, add and run the following code:"],"code":[{"lang":"python","text":"# Import the necessary module for formatting\nimport matplotlib.ticker as ticker\n\n# Create a figure and axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Plot the daily revenue data\nax.plot(days, daily_revenue, marker='o', linestyle='-', color='blue', linewidth=2, markersize=6)\n\n# Format y-axis with dollar signs\nformatter = ticker.StrMethodFormatter('${x:,.2f}')\nax.yaxis.set_major_formatter(formatter)\n\n# Add labels and title\nax.set_xlabel('Day', fontsize=12)\nax.set_ylabel('Revenue ($)', fontsize=12)\nax.set_title('Daily Revenue Over 30 Days', fontsize=14, fontweight='bold')\n\n# Add grid for better readability\nax.grid(True, linestyle='--', alpha=0.7)\n\n# Display the plot\nplt.tight_layout()\nplt.show()\n\nprint(\"Plot with dollar-formatted y-axis created!\")"},{"lang":"python","text":"formatter = ticker.StrMethodFormatter('${x:,.2f}')\nax.yaxis.set_major_formatter(formatter)"}]},{"title":"Enhancing the Plot for Better Financial Data Visualization","body":["Enhancing the Plot for Better Financial Data Visualization","Now that we have the basic currency formatting in place, let's enhance our plot further to make it more useful for financial data analysis. We'll add several improvements:","• A horizontal line showing the average daily revenue • Annotations highlighting the maximum and minimum revenue days • Customized tick parameters for better readability • A more descriptive title and legend","In a new cell in your notebook, add and run the following code:"],"code":[{"lang":"python","text":"# Import the necessary module for formatting\nimport matplotlib.ticker as ticker\n\n# Create a figure and axes\nfig, ax = plt.subplots(figsize=(12, 7))\n\n# Plot the daily revenue data\nax.plot(days, daily_revenue, marker='o', linestyle='-', color='blue',\n        linewidth=2, markersize=6, label='Daily Revenue')\n\n# Calculate statistics\navg_revenue = np.mean(daily_revenue)\nmax_revenue = np.max(daily_revenue)\nmin_revenue = np.min(daily_revenue)\nmax_day = days[np.argmax(daily_revenue)]\nmin_day = days[np.argmin(daily_revenue)]\n\n# Add a horizontal line for average revenue\nax.axhline(y=avg_revenue, color='r', linestyle='--', alpha=0.7,\n           label=f'Average Revenue: ${avg_revenue:.2f}')\n\n# Format y-axis with dollar signs\nformatter = ticker.StrMethodFormatter('${x:,.2f}')\nax.yaxis.set_major_formatter(formatter)\n\n# Customize tick parameters\nax.tick_params(axis='both', which='major', labelsize=10)\nax.yaxis.set_major_locator(ticker.MaxNLocator(nbins=10))\nax.xaxis.set_major_locator(ticker.MultipleLocator(base=5))\n\n# Add annotations for max and min revenue\nax.annotate(f'Max: ${max_revenue:.2f}', xy=(max_day, max_revenue),\n            xytext=(max_day+1, max_revenue+200),\n            arrowprops=dict(facecolor='black', shrink=0.05, width=1.5))\n\nax.annotate(f'Min: ${min_revenue:.2f}', xy=(min_day, min_revenue),\n            xytext=(min_day+1, min_revenue-200),\n            arrowprops=dict(facecolor='black', shrink=0.05, width=1.5))\n\n# Add labels and title\nax.set_xlabel('Day of Month', fontsize=12)\nax.set_ylabel('Revenue ($)', fontsize=12)\nax.set_title('Daily Revenue Analysis - 30 Day Period', fontsize=14, fontweight='bold')\n\n# Set x-axis limits to show a bit of padding\nax.set_xlim(0, 31)\n\n# Add grid for better readability"}]},{"title":"Saving the Plot and Creating a Reusable Function","body":["Saving the Plot and Creating a Reusable Function","In this final step, we'll create a reusable function to generate currency-formatted plots and save our visualization to a file. This approach makes it easy to apply the same formatting to different financial datasets in the future.","In a new cell in your notebook, add and run the following code:","After running this code, you should see:"],"code":[{"lang":"python","text":"def create_currency_plot(x_data, y_data, title='Financial Data',\n                         xlabel='X-Axis', ylabel='Amount ($)',\n                         filename=None, show_stats=True):\n    \"\"\"\n    Create a plot with currency formatting on the y-axis.\n\n    Parameters:\n    -----------\n    x_data : array-like\n        Data for the x-axis\n    y_data : array-like\n        Data for the y-axis (currency values)\n    title : str\n        Title of the plot\n    xlabel : str\n        Label for the x-axis\n    ylabel : str\n        Label for the y-axis\n    filename : str, optional\n        If provided, save the plot to this filename\n    show_stats : bool\n        Whether to show statistics (average, min, max)\n\n    Returns:\n    --------\n    fig, ax : tuple\n        The figure and axes objects\n    \"\"\"\n    # Import the necessary module for formatting\n    import matplotlib.ticker as ticker\n\n    # Create a figure and axes\n    fig, ax = plt.subplots(figsize=(12, 7))\n\n    # Plot the data\n    ax.plot(x_data, y_data, marker='o', linestyle='-', color='blue',\n            linewidth=2, markersize=6, label='Data')\n\n    if show_stats:\n        # Calculate statistics\n        avg_value = np.mean(y_data)\n        max_value = np.max(y_data)\n        min_value = np.min(y_data)\n        max_x = x_data[np.argmax(y_data)]\n        min_x = x_data[np.argmin(y_data)]\n\n        # Add a horizontal line for average value\n        ax.axhline(y=avg_value, color='r', linestyle='--', alpha=0.7,"},{"lang":"python","text":"import os\nif os.path.exists('revenue_plot.png'):\n    print(\"Plot file exists! Size:\", os.path.getsize('revenue_plot.png'), \"bytes\")\nelse:\n    print(\"Plot file was not saved correctly.\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import os\nif os.path.exists('revenue_plot.png'):\n    print(\"Plot file exists! Size:\", os.path.getsize('revenue_plot.png'), \"bytes\")\nelse:\n    print(\"Plot file was not saved correctly.\")"}],"source":"matplotlib/matplotlib · by huduo0812 · BSD 3-Clause"}};
